export class EncodeCardExport extends Redacted implements Disposable {
  readonly #arguments: ParsedArguments;
  readonly #drawing: CardDrawing;
  readonly #lifetime = SecretValue.utf16Texts([]);
  #backup: CardBackup | undefined;
  #job: OwnedCardJob | undefined;
  #pending: Promise<void> | undefined;

  constructor(
    arguments_: ParsedArguments,
    outcome: EncodeOutcome,
    drawing: CardDrawing = nodeCardRenderer,
  ) {
    super("EncodeCardExport");
    this.#arguments = {};
    // Retain only public card options, never argv's phrase, dates or unrelated output options.
    for (const key of CARD_JOB_OPTIONS) {
      const given = arguments_[key];
      if (given !== undefined) this.#arguments[key] = Array.isArray(given) ? [...given] : given;
    }
    ExportDetails.reuseForSnapshot(arguments_, this.#arguments);
    this.#backup = outcome.encoding.backup;
    this.#drawing = drawing;
  }

  /** Plans once on the first save; fresh decoded job views cannot be recalled after return. */
  async job(): Promise<CardJob> {
    this.#lifetime.assertLive();
    if (this.#job === undefined) {
      // Assign before invoking a host callback, including a callback that re-enters job().
      const pending = (this.#pending ??= Promise.resolve().then(() => this.#plan()));
      try {
        await pending;
      } finally {
        if (this.#pending === pending) this.#pending = undefined;
      }
    }
    this.#lifetime.assertLive();
    const { template, settings, values } = defined(this.#job);
    const { colors, labels, payload } = values.view;
    return {
      template,
      content: { ...settings, colors, payload, ...(labels === undefined ? {} : { labels }) },
    };
  }

  async #plan(): Promise<void> {
    this.#lifetime.assertLive();
    let values: CardValues | undefined;
    try {
      const job = await plannedCardJob(
        this.#drawing,
        cardJob(this.#arguments, defined(this.#backup)),
      );
      const { colors, labels, payload, ...settings } = job.content;
      values = new CardValues({ colors, labels, payload });
      this.#lifetime.assertLive();
      this.#job = { template: job.template, settings, values };
    } catch (error) {
      values?.wipe();
      // A failed plan is never cached; disposal also refuses a late host failure.
      this.#lifetime.assertLive();
      throw error;
    }
  }

  /**
   * Every real code and one decoy as separate files, turned as the person asked, not as a sheet.
   */
  async separateJob(): Promise<CardJob> {
    const job = await this.job();
    this.#lifetime.assertLive();
    return separateCardJob(job, parseOrientation(value(this.#arguments, "orientation")));
  }

  /** Ends cached card values immediately, without disposing the borrowed backup. */
  wipe(): void {
    this.#lifetime.wipe();
    this.#job?.values.wipe();
    this.#job = undefined;
    this.#backup = undefined;
  }

  /** Ends the owning scope after every asynchronous save/render has settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class InputBytes extends Redacted implements Disposable {
  #head: Segment | undefined;
  #tail: Segment | undefined;
  #length = 0;

  constructor() {
    super("InputBytes");
  }

  /** The number of pending bytes, without exposing their storage. */
  get length(): number {
    return this.#length;
  }

  /** Copies one octet to the end, without reallocating existing secret data. */
  push(byte: number): void {
    assertByte(byte);
    if (this.#tail === undefined || this.#tail.end === SEGMENT_BYTES) {
      const added = segment(0, undefined);
      if (this.#tail === undefined) this.#head = added;
      else this.#tail.next = added;
      this.#tail = added;
    }
    this.#tail.bytes[this.#tail.end++] = byte;
    this.#length += 1;
  }

  /** Copies a replay prefix in its original order; an invalid prefix leaves the queue unchanged. */
  prepend(bytes: readonly number[]): void {
    const copy = new Uint8Array(bytes.length);
    try {
      // Read a borrowed accessor only once: admission and insertion must use the same octet.
      for (let index = 0; index < copy.length; index += 1) {
        const byte = defined(bytes[index]);
        assertByte(byte);
        copy[index] = byte;
      }
      for (let index = copy.length - 1; index >= 0; index -= 1) {
        if (this.#head === undefined || this.#head.start === 0) {
          this.#head = segment(SEGMENT_BYTES, this.#head);
          this.#tail ??= this.#head;
        }
        this.#head.bytes[--this.#head.start] = defined(copy[index]);
        this.#length += 1;
      }
    } finally {
      copy.fill(0);
    }
  }

  /** Takes and clears the oldest byte; undefined when none remains. */
  shift(): number | undefined {
    const head = this.#head;
    if (head === undefined) return undefined;
    const byte = defined(head.bytes[head.start]);
    head.bytes[head.start++] = 0;
    this.#length -= 1;
    if (head.start === head.end) {
      this.#head = head.next;
      head.next = undefined;
      head.bytes.fill(0);
      if (this.#head === undefined) this.#tail = undefined;
    }
    return byte;
  }

  /** Whether an octet, such as Ctrl+C, is still pending. */
  includes(byte: number): boolean {
    for (let part = this.#head; part !== undefined; part = part.next)
      if (part.bytes.subarray(part.start, part.end).includes(byte)) return true;
    return false;
  }

  /** Overwrites and drops all blocks as far as the runtime permits; safe to call repeatedly. */
  wipe(): void {
    while (this.#head !== undefined) {
      const part = this.#head;
      this.#head = part.next;
      part.next = undefined;
      part.bytes.fill(0);
    }
    this.#tail = undefined;
    this.#length = 0;
  }

  /** Empties the queue when its scope ends, including after a failed terminal operation. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

