export class PrivateResult extends Redacted {
  readonly #lines: SecretValue<readonly string[]>;

  /** Owns a UTF-8 snapshot of this result's lines; no file or persistent history is involved. */
  constructor(lines: readonly string[]) {
    super("PrivateResult");
    this.#lines = SecretValue.texts(lines);
  }

  /** Shows long private results by pages; other output uses its original complete writer. */
  async show(plain: () => void): Promise<Cancelled | undefined> {
    this.#lines.assertLive();
    if (
      !PrivateSteps.active ||
      process.stdout.isTTY !== true ||
      this.#wrapped().length + this.#reserved() <= terminalRows()
    ) {
      plain();
      return undefined;
    }
    return withRawTerminal(async (next, moreWithin) => {
      if ((await dropTypedAhead()) === CANCELLED) return CANCELLED;
      let start = 0;
      let capacity = 1;
      let length = 1;
      const draw = (): void => {
        const lines = this.#wrapped();
        length = lines.length;
        capacity = Math.max(1, terminalRows() - this.#reserved());
        start = Math.min(start, Math.max(0, length - 1));
        PrivateSteps.showResult();
        process.stderr.write(CLEAR_SCREEN);
        const page = Math.floor(start / capacity) + 1;
        const pages = Math.ceil(length / capacity);
        console.error(
          [...lines.slice(start, start + capacity), `Page ${page}/${pages}`, ...NAVIGATION].join(
            "\n",
          ),
        );
      };
      process.on("SIGWINCH", draw);
      try {
        draw();
        for (;;) {
          const key = await readKey(next, moreWithin);
          if (key.kind === "cancel" || key.kind === "back") return CANCELLED;
          if (key.kind === "enter") return undefined;
          if (key.kind === "up" || key.kind === "page-up") start = Math.max(0, start - capacity);
          else if (key.kind === "down" || key.kind === "page-down")
            start = Math.min(Math.floor((length - 1) / capacity) * capacity, start + capacity);
          else if (key.kind === "home") start = 0;
          else if (key.kind === "end") start = Math.floor((length - 1) / capacity) * capacity;
          else continue;
          draw();
        }
      } finally {
        process.off("SIGWINCH", draw);
      }
    });
  }

  /** Ends this display's lifetime after the asynchronous viewer has settled. */
  wipe(): void {
    this.#lines.wipe();
  }

  /** Releases the display snapshot when its owning scope exits. */
  [Symbol.dispose](): void {
    this.wipe();
  }

  #reserved(): number {
    // Page count plus the cursor's final row; navigation wraps too on a narrow terminal.
    return 2 + NAVIGATION.reduce((rows, line) => rows + rowsOfText(line), 0);
  }

  #wrapped(): string[] {
    const columns = terminalColumns();
    return this.#lines.value.flatMap((text) =>
      text.split("\n").flatMap((line) => {
        const result: string[] = [];
        let shown = "";
        let width = 0;
        for (const point of line) {
          const cells = displayWidth(point);
          if (shown !== "" && width + cells > columns) {
            result.push(shown);
            shown = "";
            width = 0;
          }
          shown += point;
          width += cells;
        }
        result.push(shown);
        return result;
      }),
    );
  }
}

export class LinuxSandbox implements SystemSandbox {
  /** The boundaries that the kernel enforces and a probe confirmed, and what it did not. */
  readonly #record = new SandboxRecord();
  readonly #libc: Libc | undefined;
  #coreDumps: CoreDumps;

  constructor(access: SystemAccess) {
    this.#libc = this.#record.reach("the C library", access, (ffi) => new Libc(ffi));
    this.#coreDumps = this.#record.coreDumpsNotOff();
  }

  start(): void {
    const libc = this.#libc;
    if (libc === undefined) return;
    this.#coreDumps = switchOffCoreDumps(() => {
      if (libc.call.setrlimit(RLIMIT_CORE, noLimit()) !== 0)
        throw ERRORS.create("setrlimit-refused-rlimit-core-0", []);
      if (libc.call.prctl(PR_SET_DUMPABLE, 0n, 0n, 0n, 0n) !== 0)
        throw ERRORS.create("prctl-refused", []);
      if (libc.call.prctl(PR_GET_DUMPABLE, 0n, 0n, 0n, 0n) !== 0)
        throw ERRORS.create("process-still-dumpable", []);
    });
  }

  restrict(needs: SandboxNeeds): void {
    const libc = this.#libc;
    if (libc === undefined) return;
    this.#record.attempt("no_new_privs", () => {
      const set = libc.call.prctl(PR_SET_NO_NEW_PRIVS, 1n, 0n, 0n, 0n);
      if (set !== 0 || libc.call.prctl(PR_GET_NO_NEW_PRIVS, 0n, 0n, 0n, 0n) !== 1)
        throw ERRORS.create("refused-so-neither-seccomp-nor-landlock-can-used", []);
    });
    if (libc.call.prctl(PR_GET_NO_NEW_PRIVS, 0n, 0n, 0n, 0n) !== 1) return;
    this.#record.attempt("seccomp", () => this.#filter(libc, !needs.runsPrograms));
    if (!needs.writes) this.#record.attempt("Landlock", () => this.#forbidWrites(libc));
  }

  held(): readonly string[] {
    const kernel = this.#record.held;
    return kernel.length > 0 ? [`kernel: ${kernel.join(", ")}`] : [];
  }

  missing(): readonly string[] {
    return this.#record.reasons;
  }

  coreDumps(): CoreDumps {
    return this.#coreDumps;
  }

  /** Installs the seccomp filter on every thread, then probes it. */
  #filter(libc: Libc, refuseExec: boolean): void {
    const architecture = seccompArchitecture();
    if (architecture === undefined) throw ERRORS.create("no-filter", [`${process.arch}`]);
    const filter = seccompFilter(architecture, refuseExec);
    const program = Buffer.alloc(FILTER_PROGRAM_BYTES);
    program.writeUInt16LE(filter.length / INSTRUCTION_BYTES, 0);
    program.writeBigUInt64LE(libc.address(filter), FILTER_POINTER_OFFSET);
    const result = libc.syscall(
      ARCHITECTURES[architecture].seccomp,
      BigInt(SECCOMP_SET_MODE_FILTER),
      BigInt(SECCOMP_FILTER_FLAG_TSYNC),
      program,
    );
    // A positive result names a thread that could not take the filter; nothing was installed.
    if (result !== 0n)
      throw ERRORS.create("refused-every-thread", [
        `${libc.failure(result) ?? `thread ${result}`}`,
      ]);
    this.#record.claim("no sockets", sockets(libc), "a socket or an io_uring was not refused");
    if (refuseExec)
      this.#record.claim("no other programs", programs(libc), "starting a program was not refused");
  }

  /** Refuses every change to the file system on every thread, then probes it. */
  #forbidWrites(libc: Libc): void {
    const abi = libc.syscall(LANDLOCK_CREATE_RULESET, null, 0n, BigInt(CREATE_RULESET_VERSION));
    if (abi < 1n) throw ERRORS.create("switched-off-missing-kernel", []);
    const withNetwork = abi >= BigInt(NETWORK_ABI);
    const attribute = Buffer.alloc(withNetwork ? RULESET_ATTR_BYTES : RULESET_ATTR_BYTES / 2);
    attribute.writeBigUInt64LE(landlockWriteRights(Number(abi)), 0);
    if (withNetwork) attribute.writeBigUInt64LE(TCP_RIGHTS, 8);
    const ruleset = libc.syscall(LANDLOCK_CREATE_RULESET, attribute, BigInt(attribute.length), 0n);
    if (ruleset < 0n) throw ERRORS.create("ruleset-was-refused-error", [`${libc.errno()}`]);
    try {
