  }

  held(): readonly string[] {
    const sandbox = this.#record.held;
    return [
      ...(this.#attachDenied ? ["no debugger attach"] : []),
      ...(sandbox.length > 0 ? [`sandbox: ${sandbox.join(", ")}`] : []),
    ];
  }

  missing(): readonly string[] {
    return this.#record.reasons;
  }

  coreDumps(): CoreDumps {
    return this.#coreDumps;
  }
