export class BackupCheckSecrets<Mode extends MaskingMode> implements Disposable {
  readonly #mnemonic: SecretValue<string>;
  readonly #dates: SecretValue<readonly (readonly number[])[]>;
  readonly #hasDates: boolean;
  readonly #mode: Mode;
  readonly #wordCount: number;

  constructor(
    mnemonic: string,
    dates: readonly DateShiftDate[] | undefined,
    mode: Mode,
    wordCount?: number,
  ) {
    Masking.of(mode);
    const snapshot = dates === undefined ? undefined : ownedDates(dates);
    const phrase = SecretValue.text(mnemonic);
    try {
      this.#dates = SecretValue.numberLists(
        (snapshot ?? []).map(({ year, month, day }) => [year, month, day]),
      );
      this.#mnemonic = phrase;
      this.#hasDates = snapshot !== undefined;
      this.#mode = mode;
      this.#wordCount = wordCount ?? englishTokens(phrase.value).length;
    } catch (error) {
      phrase.wipe();
      throw error;
    }
  }

  /** The checked mode of the original reference, shared by every comparison. */
  get mode(): Mode {
    return this.#mode;
  }

  /** Whether checking this reference asks for dates. */
  get dated(): boolean {
    return Masking.of(this.#mode).masked;
  }

  /** Words of the reference's codes or phrase, available as metadata after disposal. */
  get wordCount(): number {
    return this.#wordCount;
  }

  /** A transient phrase view for comparison; no immutable phrase is retained. */
  get mnemonic(): string {
    return this.#mnemonic.value;
  }

  /** Complete date views; undefined preserves the distinction between unknown and no dates. */
  get dates(): readonly DateShiftDate[] | undefined {
    this.assertLive();
    if (!this.#hasDates) return undefined;
    return this.#dates.value.map((parts) => ({
      year: defined(parts[0]),
      month: defined(parts[1]),
      day: defined(parts[2]),
    }));
  }

  /** Refuses a comparison or publication after disposal, including after an awaited restore. */
  assertLive(): void {
    this.#mnemonic.assertLive();
  }

  /** Overwrites reference buffers as far as the runtime permits; repeat calls are harmless. */
  wipe(): void {
    this.#mnemonic.wipe();
    this.#dates.wipe();
  }

  /** Ends the containing check's reference-material lifetime. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class KeptShares extends Redacted implements Disposable {
  readonly #texts: SecretValue<readonly string[]>;
  readonly #places: readonly number[];
  readonly #notes: readonly string[];

  private constructor(kept: readonly TypedShare[], notes: readonly string[]) {
    super("KeptShares");
    this.#places = Object.freeze(kept.map((share) => share.place));
    this.#notes = Object.freeze([...notes]);
    this.#texts = SecretValue.utf16Texts(kept.map((share) => share.text));
  }

  /**
   * Snapshots `texts` in their order, dropping exact copies by ShareInput's rule. Complete shares
   * must read; the host first obtains unreadable-share findings from ShareBackupCheck.
   */
  static of(texts: readonly string[]): KeptShares {
    const typed: TypedShare[] = texts.map((text, index) => ({ place: index + 1, text }));
    const complete = completeOf(typed);
    const copies = ShareInput.copiesOf(complete);
    const copied = new Set(copies.map((copy) => copy.place));
    return new KeptShares(
      typed.filter((share) => !copied.has(share.place)),
      copies.map((copy) => copy.message),
    );
  }

  /** A fresh view of the shares kept, as typed; refused after this owner is wiped. */
  get texts(): readonly string[] {
    return this.#texts.value;
  }

  /** The places of the shares kept, among those typed. */
  get places(): readonly number[] {
    return this.#places;
  }

  /** One line for each copy left out. */
  get notes(): readonly string[] {
    return this.#notes;
  }

  /**
   * Why complete shares do not belong together, or are too few where no marked share can complete
   * them. Refused after disposal; every comparison uses fresh views of this owner's shares.
   */
  get setProblem(): string | undefined {
    const typed = this.texts.map((text, index) => ({ place: defined(this.#places[index]), text }));
    const complete = completeOf(typed);
    return ShareInput.completeSetProblem(complete, complete.length < typed.length);
  }

  /** Overwrites retained share buffers; earlier text views remain the caller's responsibility. */
  wipe(): void {
    this.#texts.wipe();
  }

  /** Ends the owning scope after all uses of these shares have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class RestoredShares extends Redacted implements Disposable {
  readonly #mnemonic: SecretValue<string>;
  readonly #unchecked: readonly number[];

  private constructor(mnemonic: string, unchecked: readonly number[]) {
    super("RestoredShares");
    this.#unchecked = Object.freeze([...unchecked]);
    this.#mnemonic = SecretValue.text(mnemonic);
  }

  /**
   * Snapshots the phrase of borrowed `set` and maps unchecked shares through borrowed `kept`.
   * Neither input is consumed or disposed; the result has an independent lifetime.
   */
  static of(set: ShareSet, kept: KeptShares): RestoredShares {
    const places = kept.places;
    const shares = [...set.unchecked, ...set.unsettled.map((element) => element.share)];
    const unchecked = [...new Set(shares.map((share) => defined(places[share - 1])))];
    unchecked.sort((a, b) => a - b);
    return new RestoredShares(set.mnemonic, unchecked);
  }

  /** Whether the shares hold `phrase`; refused after this owner is wiped. */
  holds(phrase: string): boolean {
    return this.#mnemonic.value === phrase;
  }

  /** Whether undoing `mode` with `dates` gives `mnemonic`; refused after disposal. */
  unmasksTo(mnemonic: string, mode: MaskedMode, dates: readonly DateShiftDate[]): boolean {
    using masked = EncodedBackup.read(this.#mnemonic.value, "english", mode);
    return masked.decode(dates).recoveredMnemonic === mnemonic;
  }

  /** Places of the shares that took no part, or that hold elements nothing settles. */
  get unchecked(): readonly number[] {
    return this.#unchecked;
  }

  /** Overwrites this owner's phrase buffer, leaving borrowed inputs and sibling owners alone. */
  wipe(): void {
    this.#mnemonic.wipe();
  }

  /** Ends the owning scope once comparisons have finished. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface BackupCheck extends Disposable {
  /** Whether the backup has dates, which are typed again too: not without Seedshift. */
  readonly dated: boolean;
  /** The words of the seed phrase, which bound the number of dates. */
  readonly wordCount: number;
  /** Checks a whole backup at once; each part is read and compared, the first finding is told. */
  check(written: WrittenBackup): Promise<BackupResult>;
  /** Ends this check's lifetime after all pending operations have settled. */
  wipe(): void;
}

export class WrittenCodes extends Redacted implements Disposable {
  readonly #mode: MaskingMode;
  readonly #codes: EncodedBackup;

  private constructor(mode: MaskingMode, codes: EncodedBackup) {
    super("WrittenCodes");
    this.#mode = mode;
    this.#codes = codes;
  }

  /**
   * Reads the codes of a backup as written down, in `format` with `mode`, unless a record names
   * its own form and mode. Throws why they cannot be read, naming places and counts only.
   */
  static read(typed: string, format: EncodedFormat, mode: MaskingMode): WrittenCodes {
    const record = parseRecord(typed);
    const codes = EncodedBackup.read(record?.payload ?? typed, record?.format ?? format, "direct");
    return new WrittenCodes(record?.mode ?? mode, codes);
  }

  get mode(): MaskingMode {
    return this.#mode;
  }

  get indexes(): readonly number[] {
    return this.#codes.indexes;
  }

  /**
   * Whether these codes and `dates` restore `mnemonic`, without handing out what they restore.
   * Throws when they cannot be undone, and for a mode that leaves several phrases, the Original
   * Seedshift with a valid last word, which only a search undoes.
   */
  restores(mnemonic: string, dates: readonly DateShiftDate[]): boolean {
    // The mode is taken only here: read as direct, a mistyped code is named by its place instead
    // of being refused for its checksum.
    using backup = this.#codes.withMode(this.#mode);
    return backup.decode(dates).recoveredMnemonic === mnemonic;
  }

  /** Overwrites the owned codes; later index reads and restores are refused. */
  wipe(): void {
    this.#codes.wipe();
  }

  /** Ends this written answer's lifetime independently of the check that read it. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class EncodedBackupCheck implements BackupCheck {
  readonly #secrets: BackupCheckSecrets<MaskingMode>;
  readonly #codes: SecretValue<readonly number[]>;
  readonly #format: EncodedFormat;

  /**
   * Whether a backup made in `mode` can be checked: not the Original Seedshift with a valid last
   * word, whose last word was replaced, so that only a search finds the seed phrase again.
   */
  static supports(mode: MaskingMode): boolean {
    return Masking.of(mode).capabilities.backupCheck;
  }

  constructor(original: EncodedOriginal) {
    const { mnemonic, format, mode, codes, dates } = original;
    if (!EncodedBackupCheck.supports(mode)) throw ERRORS.create("uncheckable", []);
    const storedCodes = SecretValue.numbers(codes);
    let secrets: BackupCheckSecrets<MaskingMode> | undefined;
    try {
      secrets = new BackupCheckSecrets(mnemonic, dates, mode, storedCodes.value.length);
      this.#codes = storedCodes;
      this.#secrets = secrets;
      this.#format = format;
    } catch (error) {
      storedCodes.wipe();
      secrets?.wipe();
      throw error;
    }
  }

  get dated(): boolean {
    return this.#secrets.dated;
  }

  get wordCount(): number {
    return this.#secrets.wordCount;
  }

  /** Reads the codes as written down (WrittenCodes.read), in the form and mode of the result. */
  readCodes(typed: string): WrittenCodes {
    this.#secrets.assertLive();
    return WrittenCodes.read(typed, this.#format, this.#secrets.mode);
  }

  /** Reads the dates as written down; throws why they cannot be read, naming dates by place. */
  readDates(line: string): readonly DateShiftDate[] {
    this.#secrets.assertLive();
    return readDates(line, this.wordCount);
  }

  /** How codes that can be read differ from those of the result: their mode, count or places. */
  compareCodes(codes: WrittenCodes): BackupFinding | undefined {
    this.#secrets.assertLive();
    const typed = codes.indexes;
    const original = this.#codes.value;
    const conflict = modeConflictOf(codes.mode, this.#secrets.mode);
    if (conflict !== undefined) return finding("codes", "mode", conflict);
    if (typed.length !== original.length)
      return finding(
        "codes",
        "count",
        `The backup has ${original.length} codes; these are ${typed.length}.`,
      );
    const places = typed.flatMap((index, place) => (index === original[place] ? [] : [place + 1]));
    if (places.length === 0) return undefined;
    return finding(
      "codes",
      "places",
      places.length === 1
        ? `The code at place ${places[0]} differs from the result.`
        : `The codes at places ${placesInWords(places)} differ from the result.`,
      places,
    );
  }

  /** How dates that can be read differ from the dates of the result. */
  compareDates(dates: readonly DateShiftDate[]): BackupFinding | undefined {
    return compareDateLists(dates, this.#secrets.dates ?? []);
  }

  /**
   * Whether the codes and the dates, each of the result, restore its seed phrase. Only a fault of
   * MnemoCode gives a finding here; it names the codes, which are then typed again.
   */
  compareRestored(codes: WrittenCodes, dates: readonly DateShiftDate[]): BackupFinding | undefined {
    if (codes.restores(this.#secrets.mnemonic, this.dated ? dates : [])) return undefined;
    return finding(
      "codes",
      "other-phrase",
      "The backup gives another seed phrase: check the codes and the dates.",
    );
  }

  async check(written: WrittenBackup): Promise<BackupResult> {
    return this.checkNow(written);
  }

  /** check, which needs nothing that answers later for codes: for a host's quick self-test too. */
  checkNow(written: WrittenBackup): BackupResult {
    this.#secrets.assertLive();
    let codes: WrittenCodes;
    try {
      codes = this.readCodes(written.backup);
    } catch (error) {
      this.#secrets.assertLive();
      return resultOf(finding("codes", "unreadable", refusalMessage(error)));
    }
    using ownedCodes = codes;
    return checkWritten(this.steps, ownedCodes, written.dates);
  }

  /** The comparisons of this check, in the shape that nextFinding runs. */
  get steps(): PartChecks<WrittenCodes> {
    this.#secrets.assertLive();
    return {
      dated: this.dated,
      wordCount: this.wordCount,
      readDates: (line) => this.readDates(line),
      compare: (codes) => this.compareCodes(codes),
      compareDates: (_codes, dates) => this.compareDates(dates),
      compareRestored: (codes, dates) => this.compareRestored(codes, dates),
    };
  }

  /** Overwrites reference phrase, code and date buffers; independently read children stay live. */
  wipe(): void {
    this.#secrets.wipe();
    this.#codes.wipe();
  }

  /** Ends the owning check scope once its comparisons have finished. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class ShareBackupCheck implements BackupCheck {
  readonly #secrets: BackupCheckSecrets<SplitMode>;
  readonly #threshold: number;
  readonly #platform: ShareRepairPlatform;
  /** The rules by which the restore reads typed shares, which the check reads them by too. */
  readonly #input: ShareInput;
  /** The phrase that shares of the result hold, when it is known (heldPhrase). */
  readonly #held: SecretValue<string> | undefined;

  /**
   * `decodeEntry` names the host's reader of an encoded seed phrase, which a phrase typed in place
   * of the shares is sent to (ShareInput).
   */
  constructor(
    original: ShareOriginal,
    platform: ShareRepairPlatform,
    texts: { readonly decodeEntry: string },
  ) {
    // A JavaScript host may pass any mode, and shares are made only in some (Masking's
    // capabilities). Another mode would ask no dates and, without the dates of the result, compare
    // nothing, so that any shares that restore would pass.
    const { mnemonic, mode, threshold, dates } = original;
    Masking.assertSplitMode(mode);
    if (!Number.isSafeInteger(threshold) || threshold < MIN_RECORDED_THRESHOLD)
      throw ERRORS.create("share-check-whole-threshold-at-least", [`${MIN_RECORDED_THRESHOLD}`]);
    const secrets = new BackupCheckSecrets(mnemonic, dates, mode);
    let storedHeld: SecretValue<string> | undefined;
    try {
      const input = new ShareInput({ decodeEntry: texts.decodeEntry });
      const held = heldPhrase({
        mnemonic: secrets.mnemonic,
        mode,
        threshold,
        dates: secrets.dates,
      });
      storedHeld = held === undefined ? undefined : SecretValue.text(held);
      this.#input = input;
      this.#held = storedHeld;
      this.#secrets = secrets;
      this.#threshold = threshold;
      this.#platform = platform;
    } catch (error) {
      storedHeld?.wipe();
      secrets.wipe();
      throw error;
    }
  }

  get dated(): boolean {
    return this.#secrets.dated;
  }

  get wordCount(): number {
    return this.#secrets.wordCount;
  }

  /** The shares asked for. */
  get threshold(): number {
    return this.#threshold;
  }

  /**
   * The shares of one answer, as the restore reads them (ShareInput.sharesOfAnswer): separated by
   * ; or line breaks, a share wrapped over lines joined again, a seed phrase refused as one; at
   * least the threshold. Throws when too few.
   */
  sharesOf(answer: string): string[] {
    this.#secrets.assertLive();
    const shares = this.#input.sharesOfAnswer(answer);
    if (shares.length < this.threshold)
      throw ERRORS.create("shares-refused", [tooFewShares(shares.length, this.threshold)]);
    return shares;
  }

  /**
   * Why the share at `place` cannot be read, or undefined when it can, as the restore says it
   * (ShareInput.readProblem): a share with ? for an unreadable element is read with the others, by
   * the restore, once its marks are few enough.
   */
  shareProblem(place: number, text: string): string | undefined {
    this.#secrets.assertLive();
    return this.#input.readProblem(place, text);
  }

  /** Reads the dates as written down; throws why they cannot be read, naming dates by place. */
  readDates(line: string): readonly DateShiftDate[] {
    this.#secrets.assertLive();
    return readDates(line, this.wordCount);
  }

  /**
   * Restores the shares kept (ShareSet.combine); throws why they cannot be, after which they are
   * all typed again. The set names each share by its place among those typed.
   */
  async restore(kept: KeptShares): Promise<RestoredShares> {
    this.#secrets.assertLive();
    const texts = kept.texts;
    const count = texts.length;
    if (count < this.threshold)
      throw ERRORS.create("restore-refused", [
        kept.notes.length === 0
          ? tooFewShares(count, this.threshold)
          : `Once the copies are left out, ${count === 1 ? "one share is" : `${count} shares are`} left; type ${this.threshold} different shares.`,
      ]);
    // Shares of another set, or a repeated member, are named as sskr-combine names them.
    const problem = kept.setProblem;
    if (problem !== undefined) throw ERRORS.create("restore-refused-2", [problem]);
    let set: ShareSet;
    try {
      set = await ShareSet.combine(texts, this.#platform, kept.places);
    } catch (error) {
      this.#secrets.assertLive();
      throw ERRORS.create("restore-refused-3", [refusalMessage(error)], { cause: error });
    }
    using ownedSet = set;
    this.#secrets.assertLive();
    return RestoredShares.of(ownedSet, kept);
  }

  /** Whether shares that can be restored hold the phrase of the result, when it is known. */
  compareShares(restored: RestoredShares): BackupFinding | undefined {
    this.#secrets.assertLive();
    if (this.#held === undefined || restored.holds(this.#held.value)) return undefined;
    return finding(
      "shares",
      "other-phrase",
      "These shares restore another seed phrase: they are not of this backup.",
    );
  }

  /**
   * How the dates typed with shares that can be restored differ from those of the result: with
   * the dates of the result, each date is compared; without them, the seed phrase they restore.
   */
  compareDates(
    restored: RestoredShares,
    dates: readonly DateShiftDate[],
  ): BackupFinding | undefined {
    const originalDates = this.#secrets.dates;
    if (originalDates !== undefined) {
      const differs = compareDateLists(dates, originalDates);
      if (differs !== undefined) return differs;
    }
    // The dates are accepted only when the shares with them really give the seed phrase back,
    // also when they equal the dates of the result (AUD-009-FUN001).
    const mode = this.#secrets.mode;
    if (Masking.isMaskedMode(mode) && restored.unmasksTo(this.#secrets.mnemonic, mode, dates))
      return undefined;
    return finding(
      "dates",
      "other-phrase",
      "The shares with these dates give another seed phrase: check the dates and the shares.",
    );
  }

  /** Whether the shares left a part unchecked: a group not complete, or a repair not settled. */
  compareChecked(restored: RestoredShares): BackupFinding | undefined {
    this.#secrets.assertLive();
    if (restored.unchecked.length === 0) return undefined;
    return finding(
      "shares",
      "unchecked",
      "The phrase matches, but some shares or repaired elements were not checked. Supply complete groups and check the marks.",
      restored.unchecked,
    );
  }

  async check(written: WrittenBackup): Promise<BackupResult> {
    this.#secrets.assertLive();
    let texts: string[];
    try {
      texts = this.sharesOf(written.backup);
    } catch (error) {
      this.#secrets.assertLive();
      return resultOf(finding("shares", "unreadable", refusalMessage(error)));
    }
    for (const [index, text] of texts.entries()) {
      const problem = this.shareProblem(index + 1, text);
      if (problem !== undefined)
        return resultOf(finding("shares", "unreadable", problem, [index + 1]));
    }
    using kept = KeptShares.of(texts);
    texts.fill("");
    let restored: RestoredShares;
    try {
      restored = await this.restore(kept);
    } catch (error) {
      this.#secrets.assertLive();
      return resultOf(finding("shares", "unreadable", refusalMessage(error)), kept.notes);
    }
    using ownedRestored = restored;
    this.#secrets.assertLive();
    return checkWritten(this.steps, ownedRestored, written.dates, kept.notes);
  }

  /** The comparisons of this check, in the shape that nextFinding runs. */
  get steps(): PartChecks<RestoredShares> {
    this.#secrets.assertLive();
    return {
      dated: this.dated,
      wordCount: this.wordCount,
      readDates: (line) => this.readDates(line),
      compare: (restored) => this.compareShares(restored),
      compareDates: (restored, dates) => this.compareDates(restored, dates),
      compareRestored: (restored) => this.compareChecked(restored),
    };
  }

  /** Overwrites this check's reference buffers; borrowed inputs and restored children stay live. */
  wipe(): void {
    this.#secrets.wipe();
    this.#held?.wipe();
    this.#input.wipe();
  }

  /** Ends the check's lifetime; a pending restore then refuses to publish its result. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class BackupReading extends Redacted implements Disposable {
  readonly #record: Pick<MnemoCodeRecord, "mode" | "format"> | undefined;
  readonly #text: SecretValue<string>;
  readonly #words: Bip39WordCount | undefined;

  private constructor(
    record: MnemoCodeRecord | undefined,
    payload: string,
    words: Bip39WordCount | undefined,
  ) {
    super("BackupReading");
    // Keep only the header: retaining record itself would keep its immutable secret payload too.
    this.#record = record === undefined ? undefined : { mode: record.mode, format: record.format };
    this.#text = SecretValue.text(payload);
    this.#words = words;
  }

  get #payload(): string {
    return this.#text.value;
  }

  /**
   * Reads the record header of `text`, if it has one, and refuses at once what no answer to a
   * later question can mend: a header that cannot be read, a record without Seedshift where only
   * Seedshift will do, and a Shamir share where an encoded seed phrase was asked for.
   */
  static of(text: string, rules: ReadingRules): BackupReading {
    if (rules.words !== undefined) assertWordCount(rules.words);
    const record = parseRecord(text);
    if (record !== undefined && !Masking.isMaskedMode(record.mode) && rules.seedshiftOnly)
      throw ERRORS.create("date-recovery-available-only-records-created-seedshift", []);
    const payload = record?.payload ?? text;
    // A share's own checksum makes a phrase's codes read as one only by a chance of about one in
    // four billion (transport.ts); a record header says it is no share.
    if (record === undefined && Share.reads(payload))
      throw ERRORS.create("shamir-share-not-encoded-seed-phrase-reads", [`${rules.shareReader}`]);
    return new BackupReading(record, payload, rules.words);
  }

  /**
   * The text of the codes in `format`: with the words of the phrase given, only the codes of so
   * many words from the start (EncodedForm.leadingCodes); all of them otherwise.
   */
  #payloadIn(format: EncodedFormat): string {
    if (this.#words === undefined) return this.#payload;
    return EncodedForm.of(format).leadingCodes(this.#payload, this.#words);
  }

  /** The text in the record's form, or the form its characters most likely are (#payloadIn). */
  get #likelyPayload(): string {
    return this.#payloadIn(this.#record?.format ?? EncodedForm.likely(this.#payload));
  }

  /**
   * The forms that `detect` finds the codes to fit, each tried on its own leading codes where the
   * words of the phrase were given (#payloadIn).
   */
  #fitting(detect: (payload: string) => EncodedFormat[]): EncodedFormat[] {
    if (this.#words === undefined) return detect(this.#payload);
    return ENCODED_FORMATS.filter((format) => detect(this.#payloadIn(format)).includes(format));
  }

  /**
   * Whether `text`, given in place of an encoded seed phrase, holds Shamir shares: "share" when it
   * reads as one and not as codes, "either" when it reads as both, which only the person can
   * tell; undefined when it is no share, or carries a record header, which only codes have. A
   * complete share's own checksum makes codes read as one only by a chance of about one in four
   * billion. Marked with ?, it is a share when one of its readings as a share has a solution
   * (sskr/repair.ts); word numbers and Unicode codes of 21 or 24 may then also be the codes of a
   * phrase with the same marks: with few marks the share's checksum settles it, with many they
   * are "either". A file or paste is split by ShareInput before testing each part, so later shares
   * are not mistaken for the decoy codes after the first one. Unreadable parts stay for the share
   * reader to name; any definite share sends the whole text to it.
   */
  static shareKind(text: string): ShareKind | undefined {
    if (parseRecord(text) !== undefined) return undefined;
    const parts = ShareInput.partsOfText(text);
    if (parts.length > 1) {
      let possible: ShareKind | undefined;
      for (const part of parts) {
        const kind = BackupReading.shareKind(part);
        if (kind === "share") return kind;
        possible ??= kind;
      }
      return possible;
    }
    const part = parts[0] ?? text;
    if (Share.reads(part)) return "share";
    if (!MissingCodes.marked(part)) return undefined;
    // Spaces own copies: the classifier must also end every original factory reading.
    let unknownBits: number[] = [];
    let readings: MarkedReading[] = [];
    try {
      readings = MarkedReading.of(part.trim());
      unknownBits = readings.flatMap((reading) =>
        reading.withSpace((space) => (space === undefined ? [] : [space.unknownBits])),
      );
    } catch {
      return undefined;
    } finally {
      for (const reading of new Set(readings)) reading.wipe();
    }
    if (unknownBits.length === 0) return undefined;
    // A share's checksum and layout are more than 50 bits of rules: marks of up to 32 unknown bits
    // that still meet them leave no doubt, while text of another kind meets them by chance only.
    if (unknownBits.some((bits) => bits <= SURE_SHARE_UNKNOWN_BITS)) return "share";
    return MissingCodes.formats(part).length > 0 ? "either" : "share";
  }

  /** Whether the text has an MNC1 record header, which names the mode and the form. */
  get hasRecord(): boolean {
    return this.#record !== undefined;
  }

  /**
   * The mode of the codes: the record's, or `given` by the host; undefined when neither names it,
   * and the host asks the person. Where the record and `given` differ, it is the record's, which
   * the host offers after modeConflict.
   */
  mode(given?: MaskingMode): MaskingMode | undefined {
    return this.#record?.mode ?? given;
  }

  /** The line that says that the record names another mode than `given`, or undefined. */
  modeConflict(given?: MaskingMode): string | undefined {
    return modeConflictOf(this.#record?.mode, given);
  }

  /** The line that says that the record holds codes of another form than `given`, or undefined. */
  formatConflict(given?: EncodedFormat): string | undefined {
    return formatConflictOf(this.#record?.format, given);
  }

  /**
   * The forms that the codes may be in: the record's, or `given`, or every form that they fit,
   * of which the host asks for one when there are several. Throws why the codes fit no form, as
   * the form that their characters most likely are names it.
   */
  formats(given?: EncodedFormat): EncodedFormat[] {
    return this.#formatsOf(given, detectInputFormats, () =>
      EncodedBackup.whyUnreadable(this.#likelyPayload),
    );
  }

  /**
   * The named form (#namedFormat), or every form that `detect` finds the codes to fit; throws
   * `none()` when they fit none. Complete and marked codes differ only in these two.
   */
  #formatsOf(
    given: EncodedFormat | undefined,
    detect: (payload: string) => EncodedFormat[],
    none: () => string,
  ): EncodedFormat[] {
    const named = this.#namedFormat(given);
    if (named !== undefined) return [named];
    const fitting = this.#fitting(detect);
    if (fitting.length === 0) throw ERRORS.create("formats-refused", [none()]);
    return fitting;
  }

  /**
   * The form that is named, before any is detected: the record's, which wins over `given`, the
   * host's; undefined when neither names one. Complete and marked codes take it alike
   * (AUD-012-ARC006).
   */
  #namedFormat(given: EncodedFormat | undefined): EncodedFormat | undefined {
    return this.#record?.format ?? given;
  }

  /**
   * Whether `text`, given where the words of a seed phrase were asked for, is the codes of an
   * encoded seed phrase in a form other than words: complete, or marked with ? (MissingCodes). A
   * host that reads words then says where codes are read instead.
   */
  static isCodes(text: string): boolean {
    const forms = MissingCodes.marked(text) ? MissingCodes.formats(text) : detectInputFormats(text);
    return forms.some((format) => format !== "english");
  }

  /** Whether the codes mark some that cannot be read (MissingCodes.marked), to be searched. */
  get marked(): boolean {
    if (this.#record === undefined && this.#words !== undefined) {
      // Hexadecimal Color Unicode also looks like word Unicode: a fitting form, rather than
      // that guess, decides which codes precede the decoys when no record names the form.
      const fitting = this.#fitting((payload) => MissingCodes.formats(payload));
      if (fitting.length > 0)
        return fitting.some((format) => MissingCodes.marked(this.#payloadIn(format)));
    }
    return MissingCodes.marked(this.#likelyPayload);
  }

  /**
   * The forms that the marked codes may be in: the record's, or `given`, or every form that they
   * fit (MissingCodes.formats). Throws when they fit none.
   */
  markedFormats(given?: EncodedFormat): EncodedFormat[] {
    return this.#formatsOf(
      given,
      (payload) => MissingCodes.formats(payload),
      () =>
        withJoinedMarksHint(
          `${FIT_NO_FORM}: mark each code that cannot be read with ?, in its place.`,
          this.#payload,
        ),
    );
  }

  /** The marked codes in `format`, taken as not masked until the host gives their mode. */
  missingCodes(format: EncodedFormat): MissingCodes {
    return MissingCodes.read(this.#payloadIn(format), format, "direct");
  }

  /**
   * The codes in `format`, held to the rules that need no mode: their count, and that each is a
   * code of that form (EncodedBackup.read). The host then gives them their mode (withMode), which
   * may find the checksum missing (MissingChecksumError).
   */
  codes(format: EncodedFormat): EncodedBackup {
    return EncodedBackup.read(this.#payloadIn(format), format, "direct");
  }

  /**
   * Ends this reading's payload lifetime. Header metadata remains available; child backups and
   * marked-code searches own independent copies. Returned JavaScript strings cannot be erased.
   */
  wipe(): void {
    this.#text.wipe();
  }

  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class InputTooLargeError extends Error {
  readonly code: ByteLimitErrorCode = "too-large";

  constructor(what: string, limit: number) {
    super(`${what} exceeds the ${limitName(limit)} safety limit.`);
    this.name = "InputTooLargeError";
  }
}

export type ListProtectionChoice =
  | { readonly kind: "key"; readonly recipient: string }
  | { readonly kind: "passphrase"; readonly passphrase: string }
  | { readonly kind: "none" };

export interface OwnedListProtection extends ListProtection, Disposable {
  /** Overwrites any retained secret state; public-key/open-list adapters keep no secret. */
  wipe(): void;
}

export class ScannerKeyProtection implements OwnedListProtection {
  readonly #recipient: string;

  /** Takes the key as typed, pasted or read from a file, and refuses one that is not an age key. */
  constructor(key: string) {
    this.#recipient = parseRecipient(key);
  }

  // Getters, not readonly fields, which a caller could overwrite at run time: what the object says
  // of the file must stay what protect does.
  get encrypted(): boolean {
    return true;
  }

  get description(): string {
    return "encrypted to the Scanner's key";
  }

  /** The key, age1… in lower case: a public key, which may be shown. */
  get recipient(): string {
    return this.#recipient;
  }

  protect(list: Uint8Array): Promise<Uint8Array> {
    return encryptCandidates(list, this.#recipient);
  }

  /** This adapter retains only a public recipient key; there is no secret allocation to erase. */
  wipe(): void {}

  /** Ends its owning scope; public metadata needs no erasure. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class PassphraseProtection extends Redacted implements OwnedListProtection {
  readonly #passphrase: SecretValue<string>;

  /** Takes the passphrase as typed or read from a file (parseListPassphrase). */
  constructor(text: string) {
    super("PassphraseProtection");
    this.#passphrase = SecretValue.text(parseListPassphrase(text));
  }

  // Getters, as in ScannerKeyProtection: they cannot be overwritten.
  get encrypted(): boolean {
    return true;
  }

  get description(): string {
    return "encrypted with the passphrase";
  }

  protect(list: Uint8Array): Promise<Uint8Array> {
    return encryptCandidatesWithPassphrase(list, this.#passphrase.value);
  }

  /** Erases retained passphrase bytes after all protect calls have settled. */
  wipe(): void {
    this.#passphrase.wipe();
  }

  /** Ends the owning scope's passphrase lifetime. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class NoProtection implements OwnedListProtection {
  // Getters, as in ScannerKeyProtection: a list in the open must never be reported as encrypted.
  get encrypted(): boolean {
    return false;
  }

  get description(): string {
    return "NOT encrypted";
  }

  /** The list itself, the same bytes. */
  protect(list: Uint8Array): Promise<Uint8Array> {
    CandidateFileAdmission.assertSize(list.byteLength, "plaintext");
    return Promise.resolve(list);
  }

  /** This stateless adapter retains no secret; its caller wipes each returned list. */
  wipe(): void {}

  /** Ends its owning scope; list bytes belong to each protect caller. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class CandidateFileRefusedError extends Error {
  readonly code: CandidateFileProblem;

  constructor(code: CandidateFileProblem, message: string, cause?: unknown) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = "CandidateFileRefusedError";
    this.code = code;
  }
}

export type ListOutcome =
  | { readonly kind: "list"; readonly list: CandidateListFile }
  /** More candidates than one list holds: no list is written. */
  | { readonly kind: "full" }
  /** No candidate went into it: no list is written. */
  | { readonly kind: "empty" };

export class CandidateListWriter extends Redacted {
  readonly #protection: ListProtection;
  readonly #passphrase: SecretValue<string>;

  /** `passphrase` is the BIP39 passphrase that the list stores for every record; "" stores none. */
  constructor(protection: ListProtection, passphrase = "") {
    super("CandidateListWriter");
    // The label says that the limit is the list's: BIP39 itself takes a longer passphrase.
    assertListPassphrase(passphrase, "BIP39 passphrase that the list stores");
    this.#protection = protection;
    this.#passphrase = SecretValue.text(passphrase);
  }

  /** Whether this live writer uses the same BIP39 passphrase; it never gives the passphrase out. */
  usesPassphrase(passphrase: string): boolean {
    return this.#passphrase.value === passphrase;
  }

  /** The list of `entropies`, record N for candidate N; they are this call's and wiped after it. */
  async write(entropies: Uint8Array[]): Promise<ListOutcome> {
    try {
      this.#passphrase.assertLive();
      if (!candidateListHolds(entropies.length)) return { kind: "full" };
      if (entropies.length === 0) return { kind: "empty" };
      return { kind: "list", list: await this.#encode(entropies) };
    } finally {
      wipeAll(entropies);
    }
  }

  /** The list of `phrases`, English BIP39 phrases in their order, as write() makes it. */
  async writePhrases(phrases: readonly string[]): Promise<ListOutcome> {
    this.#passphrase.assertLive();
    // Too many are told before any phrase is turned into entropy.
    if (!candidateListHolds(phrases.length)) return { kind: "full" };
    const entropies: Uint8Array[] = [];
    try {
      for (const phrase of phrases) entropies.push(mnemonicToEntropy(phrase, englishWordlist));
    } catch (error) {
      // A phrase that fails leaves the entropy made before it to be wiped.
      wipeAll(entropies);
      throw error;
    }
    return this.write(entropies);
  }

  async #encode(entropies: readonly Uint8Array[]): Promise<CandidateListFile> {
    const records = entropies.map((entropy) => ({ entropy }));
    // An empty passphrase is stored as none (CandidateList.passphrase).
    const plain = encodeCandidateList({ passphrase: this.#passphrase.value, records });
    let bytes: Uint8Array | undefined;
    let protectedBytes: Uint8Array | undefined;
    let handedOut = false;
    try {
      // A copy: a list without encryption may be the very array that is wiped below.
      protectedBytes = await this.#protection.protect(plain);
      bytes = new Uint8Array(protectedBytes);
      this.#passphrase.assertLive();
      const list = {
        bytes,
        description: this.#protection.description,
        encrypted: this.#protection.encrypted,
        records: records.length,
      };
      handedOut = true;
      return list;
    } finally {
      plain.fill(0);
      protectedBytes?.fill(0);
      if (!handedOut) bytes?.fill(0);
    }
  }

  /** Wipes this writer's BIP39 passphrase; the supplied protection is borrowed, never disposed here. */
  wipe(): void {
    this.#passphrase.wipe();
  }

  /** Ends the owning writer scope after its asynchronous uses have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class TooManyForListError extends Error {
  readonly code: CandidateListErrorCode = "too-many-for-list";

  constructor(advice: string) {
    super(
      `More than ${counting(MAX_CANDIDATE_RECORDS)} candidates, more than one list holds: ${advice}.`,
    );
    this.name = "TooManyForListError";
  }
}

export class OpenedCandidateList extends Redacted {
  /** The same admission rule for a plaintext file, encryption input, or decrypted output. */
  static assertSize(size: number): void {
    assertCandidateFileSize(size, MAX_CANDIDATE_LIST_BYTES, "plaintext candidate list");
  }

  #records: readonly { readonly entropy: Uint8Array; readonly passphrase?: Uint8Array }[];
  readonly #count: number;
  readonly #passphrases: ListPassphrases;
  #wiped = false;
  /** The UTF-8 passphrase for records without one of their own; empty bytes for none. */
  readonly #passphrase: Uint8Array;

  private constructor(list: CandidateList) {
    super("OpenedCandidateList");
    this.#records = list.records.map(({ entropy, passphrase }) => ({
      entropy,
      ...(passphrase === undefined ? {} : { passphrase: encoder.encode(passphrase) }),
    }));
    this.#passphrase = encoder.encode(list.passphrase ?? "");
    this.#count = this.#records.length;
    this.#passphrases = this.#records.some((record) => record.passphrase !== undefined)
      ? "records"
      : this.#passphrase.length === 0
        ? "none"
        : "list";
  }

  /** The list in `plain`, its decrypted bytes, which are wiped once read, also when refused. */
  static fromBytes(plain: Uint8Array): OpenedCandidateList {
    try {
      return new OpenedCandidateList(decodeCandidateList(plain));
    } finally {
      plain.fill(0);
    }
  }

  /** How many candidates the list holds. */
  get count(): number {
    return this.#count;
  }

  /** Where the passphrases come from: any record's own, else one for all, else none. */
  get passphrases(): ListPassphrases {
    return this.#passphrases;
  }

  /** The candidates in the order of the list, candidate N as N; made fresh each time. */
  candidates(): ListCandidate[] {
    if (this.#wiped) throw ERRORS.create("candidate-list-wiped", []);
    const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
    const passphrase = decoder.decode(this.#passphrase);
    return this.#records.map((record) => ({
      phrase: entropyToMnemonic(record.entropy, englishWordlist),
      passphrase: record.passphrase === undefined ? passphrase : decoder.decode(record.passphrase),
    }));
  }

  /** Wipes owned entropy/passphrase bytes and ends candidate access; count/flags remain metadata. */
  wipe(): void {
    for (const record of this.#records) {
      record.entropy.fill(0);
      record.passphrase?.fill(0);
    }
    this.#passphrase.fill(0);
    this.#records = [];
    this.#wiped = true;
  }

  [Symbol.dispose](): void {
    this.wipe();
  }
}

export type WordSearch =
  | { readonly kind: "unknown-words"; readonly places: readonly WordPlace[] }
  | { readonly kind: "missing-word"; readonly written: readonly number[] };

export interface WordSearchProgress extends SearchProgress {
  readonly matched: number;
}

export interface WordSearchRun<M extends WalletMatch = WalletMatch> extends SearchRun {
  /** Compares each candidate with the wallet; without it no candidate is compared. */
  readonly walletCheck?: WalletCheck<M> | undefined;
  /** How many candidates are kept to be shown, besides those that matched; MAX_SHOWN_CANDIDATES. */
  readonly maxShown?: number | undefined;
  /** How many entropies are kept for a candidate list; 0, the default, keeps none. */
  readonly keep?: number | undefined;
  /** Called once when the candidates are more than `keep`; throw to stop the search. */
  readonly onListFull?: (() => void) | undefined;
  /** Called at each turn with the candidates so far and those that matched. */
  readonly onProgress?: ((progress: WordSearchProgress) => void) | undefined;
}

export class WordCandidateSearch extends Redacted implements Disposable {
  readonly #values: SecretValue<readonly WordPlace[]>;
  readonly #active = new Set<() => void>();
  readonly #kind: WordSearch["kind"];
  readonly #wordCount: number;
  readonly #combinations: number;
  /** The places, counting from 0, that may hold more than one word. */
  readonly #unknownPlaces: readonly number[];

  private constructor(search: WordSearch) {
    super("WordCandidateSearch");
    assertSearch(search);
    // A copy, so that the caller's arrays cannot change the search once it is checked.
    const copy: WorkingSearch =
      search.kind === "unknown-words"
        ? { kind: search.kind, places: search.places.map((place) => [...place]) }
        : { kind: search.kind, written: [...search.written] };
    try {
      const combinations = searchCombinations(copy);
      assertSearchable(combinations);
      this.#values = SecretValue.numberLists(
        copy.kind === "unknown-words" ? copy.places : [copy.written],
      );
      this.#kind = copy.kind;
      this.#wordCount =
        copy.kind === "unknown-words" ? copy.places.length : copy.written.length + 1;
      this.#combinations = combinations;
      this.#unknownPlaces = copy.kind === "unknown-words" ? unknownPlacesOf(copy.places) : [];
    } finally {
      wipeWorkingSearch(copy);
    }
  }

  /**
   * Reads the phrase as typed. For "unknown-words" each place is a word, ?, a prefix with * or
   * words joined by |; for "missing-word" it is the words there are, one fewer than a phrase has.
   */
  static parse(text: string, kind: WordSearch["kind"]): WordCandidateSearch {
    if (kind === "unknown-words") return new WordCandidateSearch(parseUnknownWords(text));
    if (kind === "missing-word") return new WordCandidateSearch(parseMissingWord(text));
    throw ERRORS.create("unknown-search-kind", []);
  }

  /** Takes a search that a host made itself, after the same checks as a parsed one. */
  static of(search: WordSearch): WordCandidateSearch {
    return new WordCandidateSearch(search);
  }

  /** The search kind; remains available as metadata after disposal. */
  get kind(): WordSearch["kind"] {
    return this.#kind;
  }

  /** The words of every candidate: 12, 15, 18, 21 or 24. */
  get wordCount(): number {
    return this.#wordCount;
  }

  /** The combinations that the search checks, at most MAX_SEARCH_COMBINATIONS. */
  get combinations(): number {
    return this.#combinations;
  }

  /** How many candidates the search finds (expectedCandidates). */
  get expected(): ExpectedCandidates {
    return expectedCandidates(this.#snapshot());
  }

  /**
   * The places, counting from 0, that may hold more than one word; none for a missing word, whose
   * place each candidate has on its own (placesOf).
   */
  get unknownPlaces(): number[] {
    return [...this.#unknownPlaces];
  }

  /**
   * The places, counting from 0, whose words the search chose in `candidate`: the unknown places,
   * or the place of the missing word, the first of a run of equal words (insertedPlace).
   */
  placesOf(candidate: WordCandidate): number[] {
    this.#values.assertLive();
    if (this.#kind === "unknown-words") return [...this.#unknownPlaces];
    return [insertedPlace(defined(this.#values.value[0]), candidate.words)];
  }

  #snapshot(): WordSearch {
    const values = this.#values.value;
    return this.#kind === "unknown-words"
      ? { kind: this.#kind, places: values }
      : { kind: this.#kind, written: defined(values[0]) };
  }

  /**
   * The candidates in the order of docs/CANDIDATES.md, numbered from 1. A host takes as many at a
   * time as suits it, as a page does that lets its event loop run between batches, and stops when
   * it wants. Each candidate transfers to the caller, who wipes it. Disposal clears this
   * iterator's working state and refuses its next read, without wiping transferred candidates.
   */
  *candidates(): Generator<WordCandidate> {
    const values = this.#values.value.map((place) => [...place]);
    const search: WorkingSearch =
      this.#kind === "unknown-words"
        ? { kind: this.#kind, places: values }
        : { kind: this.#kind, written: defined(values[0]) };
    const source = searchCandidates(search);
    const close = (): void => {
      source.return(undefined);
      wipeWorkingSearch(search);
    };
    this.#active.add(close);
    try {
      let number = 0;
      for (const words of source) {
        this.#values.assertLive();
        number += 1;
        yield new WordCandidate(number, words);
        this.#values.assertLive();
      }
    } finally {
      close();
      this.#active.delete(close);
    }
  }

  /**
   * Runs the search with the host's services (WordSearchRun) and keeps what a host shows and
   * saves: the first `maxShown` candidates and every one that matched the wallet, each with its
   * number; the entropy of every candidate, up to `keep`, record N for candidate N. When there are
   * more candidates than `keep`, onListFull is called once: a host that throws there stops the
   * search; otherwise the entropies kept are wiped and the search goes on without them. The
   * entropies are wiped too when the search is stopped or fails. Unshown candidates are wiped
   * immediately; failures/disposal wipe all unpublished candidates. Successful and stopped
   * results transfer their shown candidates to the caller, who wipes them after use.
   */
  async run<M extends WalletMatch = WalletMatch>(
    run: WordSearchRun<M> = {},
  ): Promise<WordSearchResult<M>> {
    this.#values.assertLive();
    const maxShown = keptCount(run.maxShown, MAX_SHOWN_CANDIDATES, "maxShown");
    const keep = keptCount(run.keep, 0, "keep");
    const shown: ShownCandidate<M>[] = [];
    let entropies: Uint8Array[] = [];
    let count = 0;
    const tally = new MatchTally();
    let listFull = false;
    let stopped = false;
    let current: WordCandidate | undefined;
    const cleanup = (): void => {
      current?.wipe();
      for (const { candidate } of shown) candidate.wipe();
      wipeAll(entropies);
    };
    this.#active.add(cleanup);
    try {
      const turns = SearchTurns.of(run);
      for (const candidate of this.candidates()) {
        current = candidate;
        let kept = false;
        try {
          if (turns.stopped) {
            stopped = true;
            break;
          }
          const match =
            run.walletCheck === undefined
              ? undefined
              : await askWallet(run.walletCheck, candidate.phrase);
          this.#values.assertLive();
          // An answer that came after a stop is neither counted nor shown (AUD-015-API001).
          if (!stillRunning(run)) {
            stopped = true;
            break;
          }
          count += 1;
          if (keep > 0 && !listFull && count > keep) {
            listFull = true;
            wipeAll(entropies);
            entropies = [];
            run.onListFull?.();
            this.#values.assertLive();
          }
          tally.add(match);
          if (keep > 0 && !listFull) entropies.push(candidate.entropy());
          if (count <= maxShown || match?.matched === true) {
            shown.push(match === undefined ? { candidate } : { candidate, match });
            kept = true;
          } else candidate.wipe();
          // Every checked candidate is a phrase whose BIP39 checksum holds.
          const turn = await turns.due();
          this.#values.assertLive();
          if (turn === "stopped") {
            stopped = true;
            break;
          }
          if (turn === "turned")
            run.onProgress?.({ checked: count, found: count, matched: tally.matched });
          this.#values.assertLive();
        } finally {
          if (!kept) candidate.wipe();
          current = undefined;
        }
      }
      this.#values.assertLive();
      // A stop after the final turn still makes the result partial, with no complete list.
      if (!stillRunning(run)) stopped = true;
      if (stopped) {
        wipeAll(entropies);
        entropies = [];
      }
      const { matched, warning } = tally;
      return { shown, entropies, count, matched, warning, listFull, stopped };
    } catch (error) {
      cleanup();
      throw error;
    } finally {
      this.#active.delete(cleanup);
    }
  }

  /** Wipes retained bytes and active working state; already transferred candidates stay live. */
  wipe(): void {
    this.#values.wipeAndClose(this.#active);
  }

  /** Ends the search lifetime; asynchronous work must settle before the caller leaves its scope. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface CoinAddressMatch extends WalletMatch {
  readonly derived?: string;
}

export interface Base58CoinDescription extends CoinDescription, CoinRules {
  /** In the order they are tried: the first prefix that the decoded bytes start with names them. */
  readonly versions: readonly Base58Version[];
  /** The coin's Base58 alphabet; Bitcoin's when it has none of its own. */
  readonly alphabet?: BytesCoder;
}

export class Base58Coin extends Coin {
  readonly #versions: readonly Base58Version[];
  readonly #alphabet: BytesCoder;

  constructor(description: Base58CoinDescription) {
    super(description);
    this.#versions = Object.freeze(
      description.versions.map(({ prefix, type, testnet }) =>
        Object.freeze({ prefix: Object.freeze([...prefix]), type, testnet }),
      ),
    );
    this.#alphabet = description.alphabet ?? base58;
  }

  protected read(text: string): CoinAddress {
    return this.readBase58(text);
  }

  /** `text` as a Base58Check address of one of the coin's versions. */
  protected readBase58(text: string): CoinAddress {
    const data = checkedData(text, this.#alphabet);
    if (data === undefined) throw unreadableAddress();
    const version = this.#versions.find(({ prefix }) =>
      equalBytes(data.subarray(0, prefix.length), prefix),
    );
    if (version === undefined) throw this.notOurs();
    const hash = data.subarray(version.prefix.length);
    // Every Base58Check address commits to 20 bytes: a HASH160, or Tron's Keccak account.
    if (hash.length !== HASH160_BYTES) throw invalidAddress(WRONG_LENGTH);
    // Base58 writes given bytes in one way only, so the address as typed is its standard form.
    return this.address(version.type, hash, text, version.testnet);
  }
}

export class AddressRefusalError extends Error {
  readonly reason: string;
  readonly code: AddressRefusalKind;

  constructor(reason: string, code: AddressRefusalKind = "other") {
    super(`The address cannot be used for the check: ${reason}.`);
    this.name = "AddressRefusalError";
    this.reason = reason;
    this.code = code;
  }
}

export abstract class Coin implements CoinDescription {
  readonly #id: CoinId;
  readonly #name: string;
  readonly #addressForms: string;
  readonly #coinTypes: readonly number[];
  readonly #testnetAddressForms: string | undefined;
  readonly #commitments: Readonly<Partial<Record<AddressType, KeyCommitment>>>;
  readonly #purposes: Readonly<Partial<Record<AddressType, number>>>;

  constructor(description: CoinDescription & CoinRules) {
    this.#id = description.id;
    this.#name = description.name;
    this.#addressForms = description.addressForms;
    this.#testnetAddressForms = description.testnetAddressForms;
    this.#coinTypes = Object.freeze([...description.coinTypes]);
    this.#commitments = Object.freeze({ ...description.commitments });
    this.#purposes = Object.freeze({ ...description.purposes });
  }

  /** The stable identifier under which a host registers this coin. */
  get id(): CoinId {
    return this.#id;
  }

  /** The coin's name for a person. */
  get name(): string {
    return this.#name;
  }

  /** How the coin's supported main-network addresses begin. */
  get addressForms(): string {
    return this.#addressForms;
  }

  /** The owned, read-only SLIP-44 coin types of the main network's paths. */
  get coinTypes(): readonly number[] {
    return this.#coinTypes;
  }

  /**
   * How the coin's addresses begin on the main network, or on its test network where `testnet`
   * and they differ there (testnetAddressForms): what a question names beside the coin.
   */
  addressFormsOn(testnet: boolean): string {
    return testnet ? (this.#testnetAddressForms ?? this.addressForms) : this.addressForms;
  }

  /** What an address of `type` commits to for `publicKey`: its HASH160 unless the family says. */
  commitmentOf(type: AddressType, publicKey: Uint8Array): Uint8Array {
    return (this.#commitments[type] ?? hash160)(publicKey);
  }

  /**
   * The path of the branch that holds an address of `type` at `location`, with `coinType`: BIP44's
   * shape, its first step the purpose of the type (BIP44's 44 unless the family says).
   */
  branchPathOf(type: AddressType, coinType: number, location: AddressLocation): string {
    return `${this.accountPathOf(type, coinType, location.account)}/${location.branch}`;
  }

  /**
   * The path of the account `account` that holds addresses of `type`, with `coinType`:
   * m/purpose'/coin'/account', the purpose of the type (BIP44's 44 unless the family says).
   */
  accountPathOf(type: AddressType, coinType: number, account: number): string {
    return `m/${this.purposeOf(type)}'/${coinType}'/${account}'`;
  }

  /** The coin types of the coin's paths: its own, or coin type 1 on every test network. */
  coinTypesOn(testnet: boolean): readonly number[] {
    return testnet ? [TESTNET_COIN_TYPE] : this.coinTypes;
  }

  /** The paths of the branch at `location` for addresses of `type`, one for each coin type. */
  branchPathsOf(type: AddressType, testnet: boolean, location: AddressLocation): string[] {
    const owned = checkedAddressLocation(location);
    return this.coinTypesOn(testnet).map((coinType) => this.branchPathOf(type, coinType, owned));
  }

  /** The paths of the account `account` for addresses of `type`, one for each coin type. */
  accountPathsOf(type: AddressType, testnet: boolean, account: number): string[] {
    return this.coinTypesOn(testnet).map((coinType) => this.accountPathOf(type, coinType, account));
  }

  /** The first step of the paths of addresses of `type`: BIP44's 44 unless the family says. */
  purposeOf(type: AddressType): number {
    return this.#purposes[type] ?? BIP44_PURPOSE;
  }

  /**
   * `text` as a single-key receiving address of this coin; refused, naming why, when it belongs
   * to another coin, to a script or to several keys, is damaged, or is out of reach (shielded).
   * A host checks an answer with it at once: no secret is needed.
   */
  parse(text: string): CoinAddress {
    const trimmed = trimWhiteSpace(text);
    try {
      return this.read(trimmed);
    } catch (error) {
      // What this coin cannot read but is valid in another coin's form is that coin's address;
      // with this coin's own prefix it is this coin's, damaged.
      if (
        error instanceof AddressRefusalError &&
        error.code === "unreadable" &&
        !startsWithAny(trimmed, this.ownPrefixes) &&
        writtenAsAnAddress(trimmed)
      )
        throw this.notOurs();
      throw error;
    }
  }

  /**
   * How the coin's addresses in a form with a prefix begin, such as "bc1" or "bitcoincash:": an
   * address so written that cannot be read is this coin's, damaged, not another coin's.
   */
  protected get ownPrefixes(): readonly string[] {
    return [];
  }

  /**
   * What a person calls an address of `type`, where the coin has several kinds; none here. The
   * network is the address's to name (CoinAddress.description).
   */
  describe(_type: AddressType): string | undefined {
    return undefined;
  }

  /** The refusal of a shielded address, which no key of the wallet's paths gives: use `instead`. */
  protected shielded(instead: string): Error {
    return invalidAddress(`it is shielded; use ${instead} address of the same wallet`);
  }

  /** Reads the trimmed `text`, as the family writes its addresses. */
  protected abstract read(text: string): CoinAddress;

  /** The address of this coin that `text`, its standard form, names. */
  protected address(
    type: AddressType,
    commitment: Uint8Array,
    text: string,
    testnet = false,
  ): CoinAddress {
    return new CoinAddress(this, type, commitment, text, testnet);
  }

  /** The refusal of an address that is not this coin's. */
  protected notOurs(): Error {
    return invalidAddress(`it is not an address of ${this.name} (${this.addressForms})`);
  }

  /** The forms of the coin's addresses of one key, which singleKeyOnly names: its address forms. */
  protected get singleKeyForms(): string {
    return this.addressForms;
  }

  /**
   * The refusal of an address of this coin that no single key gives, such as a script's, in one
   * wording for every coin and every entry, with the coin's own forms of one key.
   */
  protected singleKeyOnly(): Error {
    return invalidAddress(
      `it is not the address of a single key; only ${this.singleKeyForms} can be checked`,
      "not-single-key",
    );
  }
}

export class HexCoin extends Coin {
  /**
   * In mixed case the capitals are the EIP-55 checksum, which must hold; in one case there is none.
   */
  protected read(text: string): CoinAddress {
    const digits = hexAccountDigits(text);
    if (digits === undefined) throw this.notOurs();
    if (!isHexAccount(digits))
      throw invalidAddress(`it is not ${HEX_ACCOUNT_DIGITS} hexadecimal digits after 0x`);
    const account = hex.decode(digits.toLowerCase());
    const checksummed = eip55(account);
    if (/[a-f]/u.test(digits) && /[A-F]/u.test(digits) && digits !== checksummed)
      throw invalidAddress("its EIP-55 checksum, the mix of capital and small letters, is wrong");
    return this.address("keccak", account, `0x${checksummed}`);
  }
}

export class DatesAnswer extends Redacted {
  readonly #known: SecretValue<readonly (readonly number[])[]>;
  readonly #patternValues: SecretValue<readonly (readonly number[])[]>;
  readonly #patternKeys: SecretValue<readonly string[]>;
  /** The places, counted from 1 among the dates typed, of the dates with ?. */
  readonly #incompletePlaces: SecretValue<readonly number[]>;
  /** The combinations of the patterns, counted once: the patterns never change. */
  readonly #combinations: number;

  private constructor(
    known: readonly DateShiftDate[],
    patterns: readonly DatePattern[],
    incompletePlaces: readonly number[],
  ) {
    super("DatesAnswer");
    // The limits are checked here, not only in parse and of: a private constructor is private to
    // TypeScript alone, and a JavaScript host can call it (AUD-009-FUN001).
    if (patterns.length > MAX_INCOMPLETE_DATES)
      throw ERRORS.create("date-recovery-supports-at-most-incomplete-dates", [
        `${MAX_INCOMPLETE_DATES}`,
      ]);
    // Copied and frozen, date by date: a caller that kept a date or a pattern could otherwise
    // change it after the limits were checked (AUD-009-FUN001). Array.from reads a hole of a
    // sparse list as undefined, which is refused; map would keep it.
    const knownDates = ownedDates(known);
    const ownPatterns = Object.freeze(Array.from(patterns, (pattern) => ownedPattern(pattern)));
    const places = [...incompletePlaces];
    assertKeysFit(ownPatterns, places);
    const combinations = datePatternCombinationCount(ownPatterns, HARD_MAX_COMBINATIONS);
    if (combinations > HARD_MAX_COMBINATIONS)
      throw ERRORS.create("date-patterns-produce-more-than-combinations-which-exceeds", [
        `${counting(HARD_MAX_COMBINATIONS)}`,
      ]);
    const knownValues = SecretValue.numberLists(
      knownDates.map(({ year, month, day }) => [year, month, day]),
    );
    let patternValues: SecretValue<readonly (readonly number[])[]> | undefined;
    let patternKeys: SecretValue<readonly string[]> | undefined;
    try {
      patternValues = SecretValue.numberLists(
        ownPatterns.flatMap(({ years, months, days }) => [years, months, days]),
      );
      patternKeys = SecretValue.utf16Texts(ownPatterns.map(({ key }) => key));
      this.#incompletePlaces = SecretValue.numbers(places);
      this.#known = knownValues;
      this.#patternValues = patternValues;
      this.#patternKeys = patternKeys;
      this.#combinations = combinations;
    } catch (error) {
      knownValues.wipe();
      patternValues?.wipe();
      patternKeys?.wipe();
      throw error;
    }
  }

  /**
   * Reads the dates of one answer, as a person types them in one line. The messages name a wrong
   * date by its place and never repeat it.
   */
  static parse(line: string, rules: DatesRules): DatesAnswer {
    const typed = line.split(DATE_SEPARATORS).filter(Boolean);
    if (typed.length === 0) throw ERRORS.create("no-date", []);
    const words = phraseLength(rules.wordCount);
    if (words !== undefined && typed.length > maximumDates(words))
      throw ERRORS.create("parse-refused", [tooManyDatesMessage(words)]);
    const known: DateShiftDate[] = [];
    const patterns: DatePattern[] = [];
    const incompletePlaces: number[] = [];
    typed.forEach((text, index) => {
      const place = index + 1;
      const incomplete = isDatePattern(text);
      if (incomplete && !rules.patterns)
        throw ERRORS.create("stand-what-forgotten-only-where-mnemo-code-can", []);
      atPlaceOf(place, () => {
        if (incomplete) patterns.push(parseDatePattern(text));
        else known.push(parseDate(text));
      });
      if (incomplete) incompletePlaces.push(place);
    });
    return new DatesAnswer(known, patterns, incompletePlaces);
  }

  /**
   * The answer of dates read elsewhere, such as complete dates given as command-line options or
   * typed into separate fields, held to the same limits as `parse`. The dates with ? count as
   * typed after the complete ones.
   */
  static of(known: readonly DateShiftDate[], patterns: readonly DatePattern[] = []): DatesAnswer {
    if (known.length + patterns.length === 0) throw ERRORS.create("no-date", []);
    // Each date is checked as parse checks a typed one, and named by its place (AUD-009-API001).
    // Array.from, not map: a hole of a sparse list is then a date that is refused, not skipped.
    const ownKnown = Array.from(known, (date, index) =>
      atPlaceOf(index + 1, () => ownedDate(date)),
    );
    const ownPatterns = Array.from(patterns, (pattern, index) =>
      atPlaceOf(known.length + index + 1, () => ownedPattern(pattern)),
    );
    const places = ownPatterns.map((_, index) => known.length + index + 1);
    return new DatesAnswer(ownKnown, ownPatterns, places);
  }

  /** The complete dates, in the order typed; a copy, so that the answer stays as it was built. */
  get known(): DateShiftDate[] {
    return this.#known.value.map((parts) =>
      Object.freeze({
        year: defined(parts[0]),
        month: defined(parts[1]),
        day: defined(parts[2]),
      }),
    );
  }

  /** The dates with ? for forgotten digits, in the order typed; none when every date is whole. */
  get patterns(): DatePattern[] {
    const values = this.#patternValues.value;
    return this.#patternKeys.value.map((key, index) =>
      Object.freeze({
        key,
        years: defined(values[index * 3]),
        months: defined(values[index * 3 + 1]),
        days: defined(values[index * 3 + 2]),
      }),
    );
  }

  /** How many dates the answer holds, complete or not. */
  get count(): number {
    return this.#known.value.length + this.#patternKeys.value.length;
  }

  /** Whether a date holds ? for a forgotten digit, so that the dates must be searched. */
  get hasForgottenDigits(): boolean {
    return this.#patternKeys.value.length > 0;
  }

  /** Standalone date recovery needs a pattern; combined code recovery also accepts known dates. */
  assertIncomplete(): void {
    if (!this.hasForgottenDigits)
      throw ERRORS.create("at-least-one-date-contain-forgotten-digit-represented", []);
  }

  /**
   * The combinations of dates that the answer stands for: 1 when every date is whole, and
   * HARD_MAX_COMBINATIONS + 1 for any count above that limit.
   */
  get combinations(): number {
    this.#known.assertLive();
    return this.#combinations;
  }

  /** The places, counted from 1 among the dates typed, of the dates that hold ?. */
  get incompletePlaces(): number[] {
    return [...this.#incompletePlaces.value];
  }

  /**
   * The line that a page shows while the dates are typed: which dates hold ? and the combinations
   * they stand for, such as "Dates 2 and 3 have forgotten digits: 3,650 combinations."; undefined
   * when every date is whole.
   */
  get forgottenDigitsNote(): string | undefined {
    const places = this.incompletePlaces;
    if (places.length === 0) return undefined;
    const verb = places.length === 1 ? "has" : "have";
    return `${placesNamed("Date", places)} ${verb} forgotten digits: ${counted(this.combinations, "combination")}.`;
  }

  /** Whether a phrase of `wordCount` words takes this many dates; never for another count. */
  fitsPhrase(wordCount: number): boolean {
    const words = phraseLength(wordCount);
    return words !== undefined && this.count <= maximumDates(words);
  }

  /**
   * Why a phrase of `wordCount` words cannot take these dates, or undefined when it can or when
   * the count is not known yet (no phrase length).
   */
  tooManyFor(wordCount: number | undefined): string | undefined {
    const words = phraseLength(wordCount);
    return words !== undefined && this.count > maximumDates(words)
      ? tooManyDatesMessage(words)
      : undefined;
  }

  /** A separate owner, preserving custom pattern keys and the original typed positions. */
  copy(): DatesAnswer {
    return new DatesAnswer(this.known, this.patterns, this.incompletePlaces);
  }

  /** Overwrites this answer's retained dates, pattern values, keys and typed positions. */
  wipe(): void {
    this.#known.wipe();
    this.#patternValues.wipe();
    this.#patternKeys.wipe();
    this.#incompletePlaces.wipe();
  }

  /** Ends the owning answer scope after all uses have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface DateSearchProgress extends SearchProgress {
  /** The date combinations tried so far. */
  readonly checked: number;
  /** The date combinations of the whole search. */
  readonly total: number;
  /** The candidates with a valid BIP39 checksum so far. */
  readonly found: number;
  /** The candidates that matched the wallet so far, or every checksum-valid one without one. */
  readonly matched: number;
}

export interface DateSearchRun extends SearchRun {
  /**
   * Called after every `progressEvery` combinations, or at each turn of the search without it, as
   * every search of the library tells its progress; and after the last one.
   */
  readonly onProgress?: ((progress: DateSearchProgress) => void) | undefined;
  /** Combinations between two progress calls; at each turn of the search by default. */
  readonly progressEvery?: number | undefined;
  /** Called with every match as it is found, also those beyond `maxShown`. */
  readonly onMatch?: ((match: DateMatch) => void) | undefined;
}

export class DateSearch extends Redacted {
  readonly #indexes: SecretValue<readonly number[]>;
  readonly #dates: DatesAnswer;
  readonly #mode: SeedshiftMode;
  readonly #walletCheck: WalletCheck | undefined;
  readonly #maxShown: number;
  readonly #keep: number;

  constructor(options: DateSearchOptions) {
    super("DateSearch");
    // Copied first and the copy checked, as EncodedBackup.of checks codes: a hole or a code outside
    // the BIP39 list is refused before the search tells its size, not at its first combination.
    const { indexes: inputIndexes, dates: inputDates, mode, walletCheck, maxShown, keep } = options;
    const indexes = Array.from(inputIndexes);
    try {
      const words = indexes.length;
      assertWordCount(words);
      assertWordIndexes(indexes);
      Masking.assertMaskedMode(mode);
      if (!(inputDates instanceof DatesAnswer)) throw ERRORS.create("dates-dates-answer", []);
      if (!inputDates.fitsPhrase(words))
        throw ERRORS.create("operation-refused", [tooManyDatesMessage(words)]);
      const shown = keptCount(maxShown, MAX_SHOWN_MATCHES, "maxShown");
      const kept = keptCount(keep, 0, "keep");
      const dates = inputDates.copy();
      try {
        this.#indexes = SecretValue.numbers(indexes);
        this.#dates = dates;
      } catch (error) {
        dates.wipe();
        throw error;
      }
      this.#mode = mode;
      this.#walletCheck = walletCheck;
      this.#maxShown = shown;
      this.#keep = kept;
    } finally {
      indexes.fill(0);
    }
  }

  /** The date combinations that the search tries. */
  get combinations(): number {
    return this.#dates.combinations;
  }

  /**
   * Seconds that one call of `walletCheck` takes in this host, from a few checks of the public
   * test phrase, for estimatedSeconds. It may answer later, as a page's derivation does.
   */
  static async secondsPerCheck(walletCheck: WalletCheck, now?: MonotonicClock): Promise<number> {
    const elapsed = startTimer(now);
    for (let check = 0; check < PROBE_CHECKS; check += 1) await walletCheck(PROBE_PHRASE);
    return elapsed() / PROBE_CHECKS;
  }

  /**
   * Seconds that decoding one combination of `dates` takes in this host in `mode`, from the first
   * combinations of a search of the public phrase of `wordCount` words: for a search without a
   * wallet check it is all the work, and beside one it is still a part (estimatedSeconds).
   */
  static secondsPerCombination(
    mode: SeedshiftMode,
    dates: DatesAnswer,
    wordCount: Bip39WordCount,
    now?: MonotonicClock,
  ): number {
    assertWordCount(wordCount);
    const elapsed = startTimer(now);
    let decoded = 0;
    for (const candidates of dateRecoveryCandidates(
      probeIndexes(wordCount),
      dates.known,
      dates.patterns,
      mode,
    )) {
      // The phrases are made as the search makes them; only the time counts.
      void candidates;
      decoded += 1;
      if (decoded >= PROBE_COMBINATIONS) break;
    }
    return elapsed() / Math.max(1, decoded);
  }

  /**
   * The pace of this search in this host: one wallet check (secondsPerCheck), 0 without one, and
   * the decoding of one combination (secondsPerCombination), for estimatedSeconds.
   */
  async pace(now?: MonotonicClock): Promise<SearchPace> {
    this.#indexes.assertLive();
    return {
      perCheck:
        this.#walletCheck === undefined
          ? 0
          : await DateSearch.secondsPerCheck(this.#walletCheck, now),
      perCombination: DateSearch.secondsPerCombination(
        this.#mode,
        this.#dates,
        this.#indexes.value.length as Bip39WordCount,
        now,
      ),
    };
  }

  /**
   * The checksum-valid phrases, so the wallet checks, that one combination gives on average, for
   * an estimate of the time (Masking.checksPerCombination): MnemoCode Seedshift gives a valid
   * phrase for every date; the Original Seedshift gives one only by chance, once in 2^bits; with
   * a valid last word every last word whose checksum fits is tried, 2^(11 - bits) of them.
   */
  checks(): number {
    return Masking.of(this.#mode).checksPerCombination(this.#indexes.value.length);
  }

  /**
   * About how many seconds the search takes at `pace`, as the host measured it (pace): the
   * decoding of every combination, and a wallet check of each checksum-valid phrase if there is
   * a wallet check.
   */
  estimatedSeconds(pace: SearchPace): number {
    const checks = this.#walletCheck === undefined ? 0 : this.checks();
    return this.combinations * secondsEach(pace, checks);
  }

  /**
   * The plan of the search at `pace`: asked for first when it tries more combinations than
   * `limit`, the person's own limit, or without one takes longer than QUESTION_SECONDS.
   */
  plan(pace: SearchPace, limit?: number): SearchPlan {
    const { combinations } = this;
    return SearchPlan.of(
      counted(combinations, "date combination"),
      combinations,
      this.estimatedSeconds(pace),
      limit,
    );
  }

  /** Runs the search; the host's callbacks and signal come in with `run`. */
  async run(run: DateSearchRun = {}): Promise<DateSearchResult> {
    this.#indexes.assertLive();
    const progressEvery = progressStep(run.progressEvery);
    const combinations = this.combinations;
    const shown: DateMatch[] = [];
    const kept: string[] = [];
    let checked = 0;
    let checksumValid = 0;
    let matchCount = 0;
    const turns = SearchTurns.of(run);
    const result = (stopped: boolean): DateSearchResult => ({
      combinations,
      checksumValid,
      matchCount,
      shown,
      kept,
      checked,
      stopped,
    });
    if (turns.stopped) return result(true);
    for (const candidates of dateRecoveryCandidates(
      this.#indexes.value,
      this.#dates.known,
      this.#dates.patterns,
      this.#mode,
    )) {
      const turn = await turns.due();
      this.#indexes.assertLive();
      if (turn === "stopped") return result(true);
      checked += 1;
      const turned = turn === "turned";
      for (const candidate of candidates) {
        checksumValid += 1;
        const match =
          this.#walletCheck === undefined
            ? undefined
            : await askWallet(this.#walletCheck, candidate.mnemonic);
        // An answer that came after a stop is neither counted nor published (AUD-015-API001).
        this.#indexes.assertLive();
        if (!stillRunning(run)) return result(true);
        if (match !== undefined && !match.matched) continue;
        matchCount += 1;
        if (kept.length < this.#keep) kept.push(candidate.mnemonic);
        if (shown.length >= this.#maxShown && run.onMatch === undefined) continue;
        const found: DateMatch = {
          dates: candidate.dates.map(formatDate).join(" "),
          allDates: candidate.allDates,
          mnemonic: candidate.mnemonic,
          // Only a match of the wallet at a path names one; without a check there is no key.
          ...(match?.path === undefined ? {} : { evidence: match.path }),
        };
        if (shown.length < this.#maxShown) shown.push(found);
        run.onMatch?.(found);
        this.#indexes.assertLive();
      }
      const step = progressEvery === undefined ? turned : checked % progressEvery === 0;
      if (step || checked === combinations)
        run.onProgress?.({
          checked,
          total: combinations,
          found: checksumValid,
          matched: matchCount,
        });
    }
    this.#indexes.assertLive();
    return result(!stillRunning(run));
  }

  /** Wipes this search's indexes and owned dates; the caller's date answer stays live. */
  wipe(): void {
    this.#indexes.wipe();
    this.#dates.wipe();
  }

  /** Ends the search scope after its asynchronous work has settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class EncodedBackup extends Redacted {
  readonly #indexes: SecretValue<readonly number[]>;
  readonly #format: EncodedFormat;
  readonly #mode: MaskingMode;

  /**
   * Holds the codes to the rules of `of`. They are checked here, not in `of` alone: a private
   * constructor is private to TypeScript only, and a JavaScript host can call it (AUD-009-API002).
   */
  private constructor(indexes: readonly number[], format: EncodedFormat, mode: MaskingMode) {
    super("EncodedBackup");
    // A JavaScript host may pass any value; another mode would silently decode another way.
    const masking = Masking.of(mode);
    // Refuses a value that names no form, with the form's own refusal.
    const form = EncodedForm.of(format);
    // Copied first and the copy checked: Array.from turns holes into undefined, which is refused,
    // where some() alone would skip them, and a getter cannot give the check one value and the
    // copy another.
    const codes = Array.from(indexes);
    try {
      if (!isBip39WordCount(codes.length))
        throw ERRORS.create("encoded-seed-phrase", [
          `${codes.length}`,
          `${form.unit}`,
          `${WORD_COUNTS_TEXT}`,
        ]);
      masking.assertCodes(codes);
      this.#indexes = SecretValue.numbers(codes);
    } finally {
      codes.fill(0);
    }
    this.#format = format;
    this.#mode = mode;
  }

  /**
   * Reads codes written in `format` as the codes of a seed phrase made with `mode`. Throws why
   * they cannot be, naming places and counts only; MissingChecksumError for a checksum-keeping
   * mode.
   */
  static read(text: string, format: EncodedFormat, mode: MaskingMode): EncodedBackup {
    return EncodedBackup.of(parseInput(text, format), format, mode);
  }

  /**
   * Refuses what Encode cannot make, before any secret is read: the Original Seedshift with a
   * valid last word comes only from the Original Seedshift with its replacement (`validLastWord`),
   * which no other mode has.
   */
  static assertEncodable(mode: MaskingMode, options: EncodeOptions = {}): void {
    const masking = Masking.of(mode);
    if (!masking.encodable)
      throw ERRORS.create("create-legacy-checksum-valid-record-select-legacy-seedshift", []);
    if (options.validLastWord === true && masking.withValidLastWord === undefined)
      throw ERRORS.create("legacy-checksum-word-replacement-available-only-legacy-seedshift", []);
  }

  /**
   * Encodes `mnemonic` with `mode` and `dates`, its codes written in `format`. With
   * `validLastWord`, the Original Seedshift's shifted last word, which usually fails the checksum,
   * is replaced by one with a valid checksum, and the record then names the mode that keeps it
   * (seedshift-legacy-valid); a last word that already fits is kept, and the record stays the
   * Original Seedshift's. The command line and a page encode through it, so that both write the
   * same codes and the same record.
   */
  static encode(
    mnemonic: string,
    dates: readonly DateShiftDate[],
    format: EncodedFormat,
    mode: MaskingMode,
    options: EncodeOptions = {},
  ): Encoding {
    EncodedBackup.assertEncodable(mode, options);
    const masking = Masking.of(mode);
    masking.assertDateCount(dates.length);
    const base = masking.encode(mnemonic, dates);
    const replacement = masking.withValidLastWord;
    const validLastWord = replacement?.encode(mnemonic, dates);
    const lastWordChanged =
      validLastWord !== undefined &&
      validLastWord.shiftedIndexes.at(-1) !== base.shiftedIndexes.at(-1);
    const replaced = options.validLastWord === true && lastWordChanged;
    const result = replaced ? defined(validLastWord) : base;
    const recordMode: MaskingMode = replaced ? defined(replacement).mode : mode;
    return {
      backup: EncodedBackup.of(result.shiftedIndexes, format, recordMode),
      result,
      base,
      validLastWord,
      lastWordChanged,
      replaced,
    };
  }

  /** Codes read elsewhere, as BIP39 indexes from 0 to 2047, held to the same rules as `read`. */
  static of(indexes: readonly number[], format: EncodedFormat, mode: MaskingMode): EncodedBackup {
    return new EncodedBackup(indexes, format, mode);
  }

  /**
   * Why codes that fit no form cannot be read: as the format that their characters most likely
   * are, naming places or the count only.
   */
  static whyUnreadable(text: string): string {
    const format = EncodedForm.likely(text);
    try {
      EncodedBackup.read(text, format, "direct").wipe();
    } catch (error) {
      return refusalMessage(error);
    }
    return `${FIT_NO_FORM}.`;
  }

  /** The same codes as made with `mode`, held to the rules of `of`. */
  withMode(mode: MaskingMode): EncodedBackup {
    return EncodedBackup.of(this.indexes, this.#format, mode);
  }

  get mode(): MaskingMode {
    return this.#mode;
  }

  get format(): EncodedFormat {
    return this.#format;
  }

  /** The codes as BIP39 indexes, 0 to 2047: 12, 15, 18, 21 or 24 of them. */
  get indexes(): readonly number[] {
    return this.#indexes.value;
  }

  /** How many words the seed phrase has: one code a word, as the constructor checked. */
  get words(): Bip39WordCount {
    return this.indexes.length as Bip39WordCount;
  }

  /**
   * Whether complete dates still leave several phrases: the Original Seedshift's valid last word.
   */
  get givesSeveral(): boolean {
    return Masking.of(this.#mode).givesSeveral;
  }

  /**
   * The encoded fingerprint: the BIP32 master fingerprint of the codes read as a phrase, by
   * `fingerprintOf` (the host's, with an empty BIP39 passphrase), or undefined when they are no
   * valid BIP39 phrase, as the Original Seedshift's codes usually are not. `fingerprintOf` may
   * answer at once or with a promise, which is then handed back. Compared with the one that encode
   * showed, it shows a mistyped code before any date is typed.
   */
  fingerprint<T>(fingerprintOf: (mnemonic: string) => T): T | undefined {
    return fingerprintOfValidPhrase(phraseOfIndexes(this.indexes), fingerprintOf);
  }

  /** The codes written in their form, as encode writes them. */
  text(): string {
    return EncodedForm.of(this.#format).codes(this.indexes);
  }

  /** The codes as an MNC1 record, which names their mode and form (record.ts). */
  record(): string {
    return serializeRecord(this.#mode, this.#format, this.text());
  }

  /**
   * The seed phrase that the codes and the complete `dates` give, with its checksum. A mode that
   * gives several phrases (givesSeveral) is refused: `candidates` gives them.
   */
  decode(dates: readonly DateShiftDate[]): DecodedResult {
    if (this.givesSeveral)
      throw ERRORS.create("original-seedshift-valid-last-word-gives-several-phrases", []);
    return defined(Masking.of(this.#mode).undo(this.indexes, dates)[0]);
  }

  /** Every phrase that the codes and the complete `dates` may give: one unless givesSeveral. */
  candidates(dates: readonly DateShiftDate[]): DecodedResult[] {
    return Masking.of(this.#mode).undo(this.indexes, dates);
  }

  /**
   * The phrases of fewer words that the first codes give with `dates`, where their checksum is
   * valid: what codes typed from printed cards may be, which end with decoys and so read as a
   * longer phrase whose checksum fails (owner, 2026-10-13). None for a mode that gives several
   * phrases; a shorter start that its mode refuses is left out.
   */
  shorterPhrases(dates: readonly DateShiftDate[]): ShorterPhrase[] {
    if (this.givesSeveral) return [];
    return BIP39_WORD_COUNTS.filter((words) => words < this.words).flatMap((words) => {
      let result: DecodedResult;
      try {
        using start = EncodedBackup.of(this.indexes.slice(0, words), this.#format, this.#mode);
        result = start.decode(dates);
      } catch {
        return [];
      }
      return result.checksumValid ? [{ words, result }] : [];
    });
  }
  /** Ends this backup's lifetime; callers finish every use before wiping it. */
  wipe(): void {
    this.#indexes.wipe();
  }

  /** Ends this backup's lifetime when its owning scope exits. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface CodedFailure<Code extends string = string> extends Error {
  readonly code: Code;
}

export type MaskedMode = {
  [M in MaskingMode]: (typeof VARIANTS)[M]["masked"] extends true ? M : never;
}[MaskingMode];

export class MissingChecksumError extends Error {
  readonly code: MaskingErrorCode = "missing-checksum";
  readonly mode: MaskingMode;

  constructor(mode: MaskingMode) {
    super(`These codes lack the BIP39 checksum that ${Masking.of(mode).name} gives them.`);
    this.name = "MissingChecksumError";
    this.mode = mode;
  }
}

export type Pbkdf2HmacSha512 = (
  password: string,
  salt: string,
  rounds: number,
  bytes: number,
) => Uint8Array | PromiseLike<Uint8Array>;

export type MissingCodesResult =
  | MissingCodesFound
  /** Every candidate, for the person to compare. */
  | { readonly kind: "list"; readonly rows: readonly MissingCodesRow[] }
  /** No codes fit: `message` says what to check. */
  | { readonly kind: "none"; readonly message: string }
  /** Several sets fit, which a fingerprint leaves only by chance: the wallet tells them apart. */
  | { readonly kind: "several"; readonly count: number; readonly message: string }
  /** The host stopped the search (SearchRun.signal): nothing found is told (CORE-22). */
  | { readonly kind: "stopped" };

export interface MissingCodesProgress extends SearchProgress {
  /** About how many candidates the search checks in all (MissingCodes.expected). */
  readonly total: number;
}

export interface MissingCodesRun extends SearchRun {
  /** Called as the candidates are checked: how many so far, of about how many, and found. */
  readonly onProgress?: ((progress: MissingCodesProgress) => void) | undefined;
}

export interface MissingCodesWaySearch extends Disposable {
  plan(limit?: number, now?: MonotonicClock): Promise<MissingCodesPlan>;
  run(run?: MissingCodesRun): Promise<MissingCodesResult>;
  /** Ends this prepared way, releases its inputs and refuses further planning/publication. */
  wipe(): void;
}

export interface CodesCheckRun extends SearchRun {
  /** Whether the codes, BIP39 indexes from 0 to 2047, are the right ones; may answer later. */
  readonly check: (codes: readonly number[]) => boolean | Promise<boolean>;
  /** How many codes that passed are kept; MAX_FOUND_CODES by default. */
  readonly maxFound?: number | undefined;
  /** Called at each turn with the candidates checked and those that passed. */
  readonly onProgress?: ((progress: SearchProgress) => void) | undefined;
}

export class MissingCodes extends Redacted implements Disposable {
  readonly #values: SecretValue<readonly WordPlace[]>;
  readonly #active = new Set<() => void>();
  readonly #format: EncodedFormat;
  readonly #masking: Masking;
  readonly #combinations: number;

  private constructor(places: readonly WordPlace[], format: EncodedFormat, mode: MaskingMode) {
    super("MissingCodes");
    // A JavaScript host may pass any value, which would be refused only by a later operation
    // (AUD-014-API006): refused here by the guard that complete codes have (EncodedBackup).
    const masking = Masking.of(mode);
    if (!isBip39WordCount(places.length))
      throw ERRORS.create("codes-seed-phrase", [`${places.length}`, `${WORD_COUNTS_TEXT}`]);
    if (places.every((place) => place.length === 1))
      throw ERRORS.create("no-code-marked-mark-each-code-cannot-read", []);
    // Counted and bounded as the word search counts and bounds its places (candidates.ts).
    const combinations = searchCombinations({ kind: "unknown-words", places });
    assertSearchable(combinations, NARROW_MARKED_CODES);
    this.#values = SecretValue.numberLists(places);
    this.#format = format;
    this.#masking = masking;
    this.#combinations = combinations;
  }

  get #places(): readonly WordPlace[] {
    return this.#values.value;
  }

  /**
   * Whether `text` marks codes it lacks: a ?, or in English words a prefix with * or words joined
   * by |. A host reads such codes here rather than as complete ones.
   */
  static marked(text: string): boolean {
    return /[?*|]/u.test(text);
  }

  /** Every form that the marked codes may be in, for a host that asks for one when several fit. */
  static formats(text: string): EncodedFormat[] {
    // Codes of every form may be marked; detection tries them in their order.
    return ENCODED_FORMATS.filter((format) => {
      try {
        return isBip39WordCount(placesOf(text, format).length);
      } catch {
        return false;
      }
    });
  }

  /** Reads the marked codes of `text` in `format`, taken with `mode`; throws why they cannot be. */
  static read(text: string, format: EncodedFormat, mode: MaskingMode): MissingCodes {
    return new MissingCodes(placesOf(text, format), format, mode);
  }

  /** The same codes taken with another mode. */
  withMode(mode: MaskingMode): MissingCodes {
    return new MissingCodes(this.#places, this.#format, mode);
  }

  get format(): EncodedFormat {
    return this.#format;
  }

  get mode(): MaskingMode {
    return this.#masking.mode;
  }

  get wordCount(): number {
    return this.#places.length;
  }

  /** The places, counted from 1, whose code is not known. */
  get missingPlaces(): number[] {
    return unknownPlacesOf(this.#places).map((index) => index + 1);
  }

  /** The combinations of codes that the marks leave. */
  get combinations(): number {
    return this.#combinations;
  }

  /** Whether the codes keep a BIP39 checksum of their own, which the search then holds them to. */
  get checksummed(): boolean {
    const masking = this.#masking;
    // Codes without Seedshift are the phrase itself, whose checksum BIP39 keeps: Masking says
    // otherwise for them only because such a phrase typed with a wrong checksum is still decoded
    // and shown with a warning, not refused.
    return masking.keepsChecksum || !masking.masked;
  }

  /**
   * About how many candidates the search checks: the combinations that pass the checksum, one in
   * 2^bits, where the codes keep one; every combination where they keep none.
   */
  get expected(): number {
    if (!this.checksummed) return this.#combinations;
    return expectedCandidates({ kind: "unknown-words", places: this.#places }).count;
  }

  /**
   * Candidates in steady order, each a caller-owned copy. Ending this owner closes active
   * iterators; a new iteration after disposal is refused.
   */
  candidates(): Generator<number[]> {
    this.#values.assertLive();
    const iterator = this.#iterate((active) => {
      if (active) this.#active.add(close);
      else this.#active.delete(close);
    });
    const finish = iterator.return.bind(iterator);
    const close = (): void => {
      finish(undefined);
    };
    return iterator;
  }

  *#iterate(state: (active: boolean) => void): Generator<number[], void, unknown> {
    this.#values.assertLive();
    state(true);
    try {
      const places = this.#places;
      if (this.checksummed) {
        for (const words of searchCandidates({ kind: "unknown-words", places })) yield [...words];
      } else {
        for (const codes of placeCombinations(places)) yield [...codes];
      }
    } finally {
      state(false);
    }
  }

  /**
   * Checks every candidate with the host's check, letting its event loop run now and then, and
   * keeps the first maxFound that pass, as EncodedBackups of this form and mode. Returned backups
   * belong to the caller, including stopped partial results. A failed run wipes its kept backups;
   * the codes must stay live until the run ends.
   */
  async run(run: CodesCheckRun): Promise<CodesCheckResult> {
    this.#values.assertLive();
    const maxFound = keptCount(run.maxFound, MAX_FOUND_CODES, "maxFound", 1);
    const found: EncodedBackup[] = [];
    let count = 0;
    let passed = 0;
    const turns = SearchTurns.of(run);
    try {
      for (const codes of this.candidates()) {
        if (turns.stopped) return { found, passed, count, stopped: true };
        const passes = await run.check(codes);
        this.#values.assertLive();
        // An answer that came after a stop is not counted (AUD-015-API001).
        if (turns.stopped) return { found, passed, count, stopped: true };
        count += 1;
        if (passes) {
          passed += 1;
          if (found.length < maxFound) found.push(EncodedBackup.of(codes, this.#format, this.mode));
        }
        const turn = await turns.due();
        this.#values.assertLive();
        if (turn === "stopped") return { found, passed, count, stopped: true };
        if (turn === "turned") run.onProgress?.({ checked: count, found: passed });
      }
      this.#values.assertLive();
      // The final progress callback can stop the run after its last turn.
      return { found, passed, count, stopped: turns.stopped };
    } catch (error) {
      for (const backup of found) backup.wipe();
      throw error;
    }
  }

  /** Ends the retained code lifetime and closes every active candidate iterator; idempotent. */
  wipe(): void {
    this.#values.wipeAndClose(this.#active);
  }

  [Symbol.dispose](): void {
    this.wipe();
  }
}

export type ReEncodingConfirmation =
  | { readonly by: "person" }
  | {
      readonly by: "wallet";
      readonly path: string | undefined;
      readonly warning: string | undefined;
    };

export class ReEncoding extends Redacted {
  readonly #indexes: SecretValue<readonly number[]>;
  readonly #dates: SecretValue<readonly (readonly number[])[]>;
  readonly #shifts: SecretValue<readonly number[]>;
  readonly #checksumValid: boolean;
  #confirmation: ReEncodingConfirmation | undefined;

  private constructor(result: DecodedResult) {
    super("ReEncoding");
    // Own every decoded field: a returned view or a caller's date must not change what a wallet
    // checked while its answer was awaited (AUD-021-API002).
    const dates = ownedDates(result.dates);
    const { recoveredIndexes, shifts, checksumValid } = result;
    const indexes = SecretValue.numbers(recoveredIndexes);
    let dateValues: SecretValue<readonly (readonly number[])[]> | undefined;
    try {
      dateValues = SecretValue.numberLists(dates.map(({ year, month, day }) => [year, month, day]));
      this.#shifts = SecretValue.numbers(shifts);
      this.#indexes = indexes;
      this.#dates = dateValues;
      this.#checksumValid = checksumValid;
    } catch (error) {
      indexes.wipe();
      dateValues?.wipe();
      throw error;
    }
  }

  /** Builds a transient compatibility view; the owner retains only mutable bytes. */
  get #result(): DecodedResult {
    const indexes = this.#indexes.value;
    return Object.freeze({
      recoveredMnemonic: phraseOfIndexes(indexes),
      recoveredIndexes: indexes,
      dates: ownedDates(
        this.#dates.value.map((parts) => ({
          year: defined(parts[0]),
          month: defined(parts[1]),
          day: defined(parts[2]),
        })),
      ),
      shifts: this.#shifts.value,
      checksumValid: this.#checksumValid,
    });
  }

  /**
   * The phrase that `backup` and its complete `dates` give, as Decode decodes it; refused where it
   * fails its checksum (CHECKSUM_FAILS). A backup that gives several phrases, one for each possible
   * last word (EncodedBackup.givesSeveral), takes the original `lastWord` that picks one, which no
   * other backup takes (LAST_WORD_NOT_TAKEN), so that a mistaken mode is said, not ignored.
   */
  static of(backup: EncodedBackup, dates: readonly DateShiftDate[], lastWord?: string): ReEncoding {
    if (backup.givesSeveral) return ReEncoding.#withLastWord(backup.candidates(dates), lastWord);
    if (lastWord !== undefined) throw ERRORS.create("last-word-not-taken", []);
    const result = backup.decode(dates);
    if (!result.checksumValid) throw ERRORS.create("checksum-fails", []);
    return new ReEncoding(result);
  }

  /**
   * The candidate of a backup with a valid last word that ends with `lastWord`, as typed; refused
   * without it (LAST_WORD_NEEDED) or where none ends with it (NO_SUCH_LAST_WORD). Each candidate
   * has a last word of its own, so that at most one ends with it.
   */
  static #withLastWord(
    candidates: readonly DecodedResult[],
    lastWord: string | undefined,
  ): ReEncoding {
    if (lastWord === undefined) throw ERRORS.create("last-word-needed", []);
    const typed = englishTokens(lastWord);
    const found =
      typed.length === 1
        ? candidates.find(
            (candidate) => englishTokens(candidate.recoveredMnemonic).at(-1) === typed[0],
          )
        : undefined;
    if (found === undefined) throw ERRORS.create("no-such-last-word", []);
    return new ReEncoding(found);
  }

  /** The seed phrase, for the host to show before it is confirmed. */
  get phrase(): string {
    return this.#result.recoveredMnemonic;
  }

  /** The owned, immutable decoded result, including its index, date and shift views. */
  get result(): DecodedResult {
    return this.#result;
  }

  /** How it was confirmed; undefined until it is. */
  get confirmation(): ReEncodingConfirmation | undefined {
    return this.#confirmation;
  }

  /**
   * The person says that this is the phrase to encode again: they recognise it or its fingerprint,
   * or they gave no wallet to compare it with on a command line of their own.
   */
  confirmByPerson(): void {
    this.#indexes.assertLive();
    this.#confirmation = Object.freeze({ by: "person" });
  }

  /**
   * Compares the phrase with the wallet that `check` holds, the host's derivation of the address
   * or fingerprint the person named; a match confirms it. The answer is held to the contract of
   * every wallet check (askWallet): only matched === true confirms. A host shows the match's
   * warning, if it has one, before confirmationLine: a fingerprint is only a filter
   * (FINGERPRINT_WARNING), so that its match only accepts the phrase.
   */
  async confirmByWallet<M extends WalletMatch>(check: WalletCheck<M>): Promise<M> {
    const phrase = this.#result.recoveredMnemonic;
    const match = await askWallet(check, phrase);
    // A host may end the owner's lifetime while its wallet check is awaited.
    this.#indexes.assertLive();
    if (match.matched) {
      this.#confirmation = Object.freeze({
        by: "wallet",
        path: match.path,
        warning: match.warning,
      });
    }
    return match;
  }

  /**
   * The line that says how the phrase was confirmed, `by` naming what the host compared it with:
   * the person's recognition; a match whose check gave a warning, such as a fingerprint's, only as
   * accepted, not proven (AUD-020-SEC001); otherwise where the wallet matched. Refused until it is
   * confirmed (NOT_CONFIRMED).
   */
  confirmationLine(by: MatchedBy): string {
    const confirmation = this.#confirmation;
    if (confirmation === undefined) throw ERRORS.create("not-confirmed", []);
    if (confirmation.by === "person") return RE_ENCODING_WORDS.recognised;
    if (confirmation.warning !== undefined)
      return `The ${by} matches: the seed phrase is accepted, not proven.`;
    if (confirmation.path === undefined || isMasterKeyPath(confirmation.path))
      return "The wallet matches: the seed phrase is confirmed.";
    return `${capitalized(by)} found at ${confirmation.path}: the wallet matches, the seed phrase is confirmed.`;
  }

  /** The phrase to encode again; refused until it is confirmed (NOT_CONFIRMED). */
  confirmedPhrase(): string {
    this.#indexes.assertLive();
    if (this.#confirmation === undefined) throw ERRORS.create("not-confirmed", []);
    return this.phrase;
  }

  /** Overwrites retained indexes, dates and shifts and forgets the confirmation. */
  wipe(): void {
    this.#indexes.wipe();
    this.#dates.wipe();
    this.#shifts.wipe();
    this.#confirmation = undefined;
  }

  /** Ends this owner's lifetime, independently of the backup borrowed by of(). */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface SeedshiftAnswer extends Answer {
  readonly source: string;
  readonly dates: readonly string[];
}

export class SecretValue<Value> extends Redacted implements Disposable {
  readonly #bytes: Uint8Array;
  readonly #decode: (bytes: Uint8Array) => Value;
  #wiped = false;

  private constructor(bytes: Uint8Array, decode: (bytes: Uint8Array) => Value) {
    super("SecretValue");
    this.#bytes = bytes;
    this.#decode = decode;
  }

  /** Retains UTF-8 bytes, dropping the input string after construction. */
  static text(text: string): SecretValue<string> {
    if (typeof text !== "string") throw ERRORS.create("text", []);
    return new SecretValue(ENCODER.encode(text), (bytes) => DECODER.decode(bytes));
  }

  /** Retains finite numbers in binary64 bytes; numeric meaning is checked by the domain owner. */
  static numbers(values: readonly number[]): SecretValue<readonly number[]> {
    const bytes = encodedNumbers(values);
    return new SecretValue(bytes, (storage) =>
      decodedNumbers(storage, 0, storage.length / NUMBER_BYTES),
    );
  }

  /** Retains arbitrary signed integers without a lossy conversion through Number. */
  static bigints(values: readonly bigint[]): SecretValue<readonly bigint[]> {
    if (!Array.isArray(values)) throw ERRORS.create("bigints", []);
    const copy = Array.from<bigint>(values);
    if (!copy.every((value) => typeof value === "bigint")) throw ERRORS.create("bigints", []);
    // Only transient decimal strings reach the existing text encoder. The retained decoder
    // captures item lengths, not these immutable values or the temporary storage owner.
    using encoded = SecretValue.texts(copy.map((value) => value.toString()));
    const decode = encoded.#decode;
    return new SecretValue(Uint8Array.from(encoded.#bytes), (bytes) =>
      Object.freeze(decode(bytes).map((value) => BigInt(value))),
    );
  }

  /** Retains independent numeric lists; only their lengths are kept outside the byte storage. */
  static numberLists(
    values: readonly (readonly number[])[],
  ): SecretValue<readonly (readonly number[])[]> {
    if (!Array.isArray(values)) throw ERRORS.create("numbers", []);
    const rows = Array.from<readonly number[]>(values);
    const copy: number[][] = [];
    let flat: number[] = [];
    try {
      for (const row of rows) {
        if (!Array.isArray(row)) throw ERRORS.create("numbers", []);
        copy.push(Array.from<number>(row));
      }
      flat = copy.flat();
      const lengths = copy.map((values) => values.length);
      const bytes = encodedNumbers(flat);
      return new SecretValue(bytes, (storage) => {
        let start = 0;
        return Object.freeze(
          lengths.map((count) => {
            const values = decodedNumbers(storage, start, count);
            start += count;
            return values;
          }),
        );
      });
    } finally {
      for (const values of copy) values.fill(0);
      flat.fill(0);
    }
  }

  /** Retains UTF-8 text items; only item lengths are kept outside the byte storage. */
  static texts(values: readonly string[]): SecretValue<readonly string[]> {
    if (!Array.isArray(values)) throw ERRORS.create("text", []);
    const encoded: Uint8Array[] = [];
    try {
      for (const text of values) {
        if (typeof text !== "string") throw ERRORS.create("text", []);
        encoded.push(ENCODER.encode(text));
      }
      const lengths = encoded.map((bytes) => bytes.length);
      const bytes = new Uint8Array(lengths.reduce((sum, length) => sum + length, 0));
      let offset = 0;
      for (const part of encoded) {
        bytes.set(part, offset);
        offset += part.length;
      }
      return new SecretValue(bytes, (storage) => {
        let start = 0;
        return Object.freeze(
          lengths.map((length) => {
            const text = DECODER.decode(storage.subarray(start, start + length));
            start += length;
            return text;
          }),
        );
      });
    } finally {
      for (const bytes of encoded) bytes.fill(0);
    }
  }

  /** Retains opaque JS strings losslessly as UTF-16 code units, including lone surrogates. */
  static utf16Texts(values: readonly string[]): SecretValue<readonly string[]> {
    if (!Array.isArray(values)) throw ERRORS.create("text", []);
    const texts = Array.from<string>(values);
    if (!texts.every((text) => typeof text === "string")) throw ERRORS.create("text", []);
    const lengths = texts.map((text) => text.length);
    const bytes = new Uint8Array(
      lengths.reduce((sum, length) => sum + length, 0) * CODE_UNIT_BYTES,
    );
    const view = new DataView(bytes.buffer);
    let offset = 0;
    for (const text of texts) {
      for (let index = 0; index < text.length; index += 1) {
        view.setUint16(offset * CODE_UNIT_BYTES, text.charCodeAt(index), true);
        offset += 1;
      }
    }
    return new SecretValue(bytes, (storage) => {
      const stored = new DataView(storage.buffer, storage.byteOffset, storage.byteLength);
      let start = 0;
      return Object.freeze(
        lengths.map((length) => {
          const text = decodedCodeUnits(stored, start, length);
          start += length;
          return text;
        }),
      );
    });
  }

  /** Refuses a read or publication after the owner ended the lifetime, including across an await. */
  assertLive(): void {
    if (this.#wiped) throw ERRORS.create("wiped", []);
  }

  /** A freshly decoded view; the owner retains only bytes after this call returns. */
  get value(): Value {
    this.assertLive();
    return this.#decode(this.#bytes);
  }

  /** A separate owner with its own byte copy and the same decoding contract. */
  copy(): SecretValue<Value> {
    this.assertLive();
    return new SecretValue(Uint8Array.from(this.#bytes), this.#decode);
  }

  /** Overwrites this owner's bytes as far as the runtime allows and refuses further reads. */
  wipe(): void {
    this.#bytes.fill(0);
    this.#wiped = true;
  }

  /**
   * Ends this value and its active local work. Clears the registry before calling its closures,
   * so reentrant disposal is harmless; every closure runs even if another one fails.
   */
  wipeAndClose(active: Set<() => void>): void {
    this.wipe();
    const closing = [...active];
    active.clear();
    const failures: unknown[] = [];
    for (const close of closing) {
      try {
        close();
      } catch (error) {
        failures.push(error);
      }
    }
    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw ERRORS.create("cleanup", [], { cause: Object.freeze(failures) });
  }

  /** Ends this owner's lifetime, also when a using scope exits through a failure. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export type WalletCheck<M extends WalletMatch = WalletMatch> = (
  mnemonic: string,
) => M | PromiseLike<M>;

export class PreparedWalletEvidence extends Redacted implements Disposable {
  readonly #seed: Bip39Seed;
  readonly #passphrase: SecretValue<readonly string[]>;
  readonly #versions: Versions;
  #expected: Comparison | undefined;

  /** Takes validated evidence from its factory; closes that evidence if construction fails. */
  constructor(seed: Bip39Seed, expected: Comparison, versions: Versions, passphrase: string) {
    super("PreparedWalletEvidence");
    try {
      Bip39Seed.assertPassphraseType(passphrase);
      this.#versions = Object.freeze({ public: versions.public, private: versions.private });
      this.#passphrase = SecretValue.utf16Texts([passphrase]);
    } catch (error) {
      expected.wipe();
      throw error;
    }
    this.#seed = seed;
    this.#expected = expected;
  }

  /** Compares one phrase using a host PBKDF2 that answers synchronously; no keys are retained. */
  match(mnemonic: string): EvidenceMatch {
    const result = this.#seed.withRoot(...this.#rootInput(mnemonic));
    this.#passphrase.assertLive();
    return result;
  }

  /** The same comparison with a host PBKDF2 that may settle later; keep this owner live. */
  async matchAsync(mnemonic: string): Promise<EvidenceMatch> {
    const result = await this.#seed.withRootLater(...this.#rootInput(mnemonic));
    this.#passphrase.assertLive();
    return result;
  }

  #live(): Comparison {
    this.#passphrase.assertLive();
    return defined(this.#expected);
  }

  #rootInput(mnemonic: string) {
    return [
      mnemonic,
      defined(this.#passphrase.value[0]),
      (root: HDKey) => this.#live().compare(root),
      this.#versions,
    ] as const;
  }

  /** Ends this comparison without disposing its service or caller-owned input/results. */
  wipe(): void {
    this.#passphrase.wipe();
    const expected = this.#expected;
    this.#expected = undefined;
    expected?.wipe();
  }

  /** Ends the containing using scope after all asynchronous comparisons have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

