export class CheckedSskrBridge implements SskrBridge {
  /** A group's checked threshold/count bytes; never silently narrows host-supplied numbers. */
  static groupSpecifications(threshold: number, count: number): Uint8Array {
    if (!isRecordedQuorum(threshold, count)) throw ERRORS.create("member-quorum", []);
    return Uint8Array.of(threshold, count);
  }
  readonly #bridge: SskrBridge;
  /** The codes of the bridge's encodings: the numbers of its enum, which also maps them back. */
  readonly #encodings: readonly number[];

  constructor(bridge: SskrBridge) {
    this.#bridge = bridge;
    this.#encodings = Object.freeze(
      Object.values(bridge.ShareEncoding).filter((code) => typeof code === "number"),
    );
  }

  get ShareEncoding(): SskrBridge["ShareEncoding"] {
    return this.#bridge.ShareEncoding;
  }

  create_sskr_shares(
    secret: Uint8Array,
    group_threshold: number,
    group_specs: Uint8Array,
    random_seed: Uint8Array,
  ): string {
    return this.#create(secret, group_threshold, group_specs, random_seed);
  }

  create_sskr_shares_formatted(
    secret: Uint8Array,
    group_threshold: number,
    group_specs: Uint8Array,
    random_seed: Uint8Array,
    encoding: number,
  ): string {
    this.#assertEncoding(encoding);
    return this.#create(secret, group_threshold, group_specs, random_seed, encoding);
  }

  recover_sskr_shares(records: string): Uint8Array {
    CheckedSskrBridge.#assertRecords(records);
    return this.#bridge.recover_sskr_shares(records);
  }

  recover_sskr_shares_formatted(records: string, encoding: number): Uint8Array {
    this.#assertEncoding(encoding);
    CheckedSskrBridge.#assertRecords(records);
    return this.#bridge.recover_sskr_shares_formatted(records, encoding);
  }

  /** Admits every array before any copy, then owns and wipes the inputs passed to generated glue. */
  #create(
    secret: Uint8Array,
    threshold: number,
    groups: Uint8Array,
    seed: Uint8Array,
    encoding?: number,
  ): string {
    CheckedSskrBridge.#assertGroupThreshold(threshold);
    for (const input of [secret, groups, seed])
      if (!ByteArray.is(input)) throw ERRORS.create("byte-array-required", []);
    const owned: Uint8Array[] = [];
    try {
      for (const input of [secret, groups, seed]) owned.push(new Uint8Array(input));
      const [copy, specifications, randomness] = owned;
      // The three entries were made above; tuple construction keeps the glue inputs intrinsic.
      if (copy === undefined || specifications === undefined || randomness === undefined)
        throw ERRORS.create("byte-array-required", []);
      return encoding === undefined
        ? this.#bridge.create_sskr_shares(copy, threshold, specifications, randomness)
        : this.#bridge.create_sskr_shares_formatted(
            copy,
            threshold,
            specifications,
            randomness,
            encoding,
          );
    } finally {
      wipeAll(owned);
    }
  }

  static #assertRecords(records: unknown): void {
    if (typeof records !== "string") throw ERRORS.create("share-text-required", []);
  }

  /** Refuses anything but the code of one of the bridge's encodings, a whole number as it is. */
  #assertEncoding(encoding: unknown): void {
    if (typeof encoding !== "number" || !this.#encodings.includes(encoding))
      throw ERRORS.create("unsupported-encoding", []);
  }

  /** Refuses a group threshold that the glue's u8 would not hold as it is. */
  static #assertGroupThreshold(threshold: unknown): void {
    if (!Number.isInteger(threshold) || (threshold as number) < 0 || (threshold as number) > U8_MAX)
      throw ERRORS.create("unsupported-group-threshold", []);
  }
}

export interface RepairProgress extends SearchProgress {
  readonly total: number;
}

export interface SearchOptions extends SearchRun {
  /** Called now and then with the checks made, of all, and the phrases found so far. */
  readonly onProgress?: ((progress: RepairProgress) => void) | undefined;
}

export interface PlanOptions extends SearchRun {
  /** The host's services, with which the search checks and restores each candidate. */
  readonly platform: ShareRepairPlatform;
  /**
   * The place at which each share was typed, by its index among `records`, by which a refusal
   * names it; by its index, counted from 1, where none is given.
   */
  readonly places?: readonly number[] | undefined;
}

export interface ElementHelp extends MarkedElement {
  readonly openBits: number;
}

export interface RepairedSet extends RepairedShares {
  readonly mnemonic: string;
  /**
   * Shares, counted from 1, that took no part and were not checked: members of a group with fewer
   * than its threshold, in a set of several groups.
   */
  readonly unchecked?: readonly number[];
}

export class Branch implements Disposable {
  readonly #parts: Omit<BranchParts, "particular" | "visible" | "hidden">;
  readonly #coordinates: SecretValue<readonly bigint[]>;
  readonly #visibleCount: number;
  readonly #hiddenCount: number;
  readonly #active = new Set<() => void>();

  /** Owns the computed arrays and snapshots the coordinates; borrows the joint and its spaces. */
  constructor(parts: BranchParts) {
    const { particular, visible, hidden } = parts;
    this.#parts = {
      joint: parts.joint,
      threshold: parts.threshold,
      members: [...parts.members],
      visibleDeltas: [...parts.visibleDeltas],
      secretAndDigest: parts.secretAndDigest,
    };
    try {
      this.#coordinates = SecretValue.bigints([particular, ...visible, ...hidden]);
    } catch (error) {
      for (const array of this.secretArrays()) array.fill(0);
      throw error;
    }
    this.#visibleCount = visible.length;
    this.#hiddenCount = hidden.length;
  }

  /** The member threshold of this way to read the shares. */
  get threshold(): number {
    return this.#parts.threshold;
  }

  /** The bytes of the secret. */
  get secretBytes(): number {
    return this.#parts.joint.secretBytes;
  }

  /** Bits that only the digest can decide. */
  get openBits(): number {
    return this.#visibleCount;
  }

  /** The combinations that a search of this branch tries. */
  get combinations(): number {
    return 2 ** this.openBits;
  }

  /** The readings of the shares that the branch was solved from. */
  get spaces(): readonly ReadingSpace[] {
    return this.#parts.joint.spaces;
  }

  /** The branch's own arrays that hold a share's part of the secret: its (S, D) and changes. */
  secretArrays(): Uint8Array[] {
    return [this.#parts.secretAndDigest, ...this.#parts.visibleDeltas];
  }

  /** Those of the branch with those of the readings it was solved from. */
  allSecretArrays(): Uint8Array[] {
    return [...this.secretArrays(), ...this.#parts.joint.secretArrays()];
  }

  /** Ends this branch and active work; shared readings remain with the assessment or plan. */
  wipe(): void {
    this.#coordinates.wipeAndClose(this.#active);
    for (const array of this.secretArrays()) array.fill(0);
  }

  /** Ends the branch's owned state without disposing its borrowed joint. */
  [Symbol.dispose](): void {
    this.wipe();
  }

  #directions(): { particular: bigint; visible: readonly bigint[]; hidden: readonly bigint[] } {
    const values = this.#coordinates.value;
    return {
      particular: defined(values[0]),
      visible: values.slice(1, 1 + this.#visibleCount),
      hidden: values.slice(1 + this.#visibleCount),
    };
  }

  #pointAt(step: number): bigint {
    const { particular, visible } = this.#directions();
    const gray = BigInt(step) ^ (BigInt(step) >> 1n);
    return particular ^ combination(visible, gray);
  }

  /** Open bits of this branch if marked element `hole` of share `share` were read. */
  openBitsIfRead(share: number, hole: number): number {
    const { joint, visibleDeltas } = this.#parts;
    const { visible, hidden } = this.#directions();
    const mask = defined(joint.spaces[share]).unitMask(hole);
    // Each direction with the change it makes in (S, D): a pair, typed as one so that a host that
    // compiles with noUncheckedIndexedAccess reads both of its parts as present.
    const directions: (readonly [bigint, bigint])[] = [
      ...visible.map((direction, i): readonly [bigint, bigint] => [
        direction,
        bytesToBits(defined(visibleDeltas[i])),
      ]),
      ...hidden.map((direction): readonly [bigint, bigint] => [direction, 0n]),
    ];
    // The combinations of directions that leave this element as it is, with their images in
    // (S, D). Each pivot is a change to the element, with the image in (S, D) of the directions
    // behind it.
    const parts = new PivotBasis();
    const kept: bigint[] = [];
    for (const [direction, image] of directions) {
      const reduced = parts.add(joint.holeChange(share, direction) & mask, image);
      if (reduced.vector === 0n) kept.push(reduced.companion);
    }
    return basisOf(kept).length;
  }

  /**
   * About how many more shares would settle what this branch leaves open. Each share beyond the
   * threshold adds as many equations as the secret has bits, and `threshold` shares without marks
   * settle everything; the marks of the new shares, or equations that depend on others, can make
   * one more needed.
   */
  sharesToSettle(shares: readonly ShareAssessment[]): number {
    const { threshold, members } = this.#parts;
    if (this.openBits === 0) return 0;
    const clean = new Set(members.filter((_, share) => defined(shares[share]).marks === 0)).size;
    const byEquations = Math.ceil(this.openBits / (BITS_PER_BYTE * this.secretBytes));
    return Math.max(1, Math.min(threshold - clean, byEquations));
  }

  /**
   * Tries digest candidates in Gray-code order and confirms matches through the SSKR library.
   * Calls tried after each check, awaiting its returned turn before continuing.
   */
  async searchDigest(
    platform: ShareRepairPlatform,
    found: (set: RepairedSet) => void,
    tried: () => Promise<TurnState> | undefined,
  ): Promise<void> {
    this.#coordinates.assertLive();
    const { visibleDeltas } = this.#parts;
    const current = Uint8Array.from(this.#parts.secretAndDigest);
    const close = () => current.fill(0);
    this.#active.add(close);
    try {
      for (let step = 0; step < this.combinations; step += 1) {
        this.#coordinates.assertLive();
        if (step > 0) {
          xorInto(current, defined(visibleDeltas[lowestBit(step)]));
        }
        if (digestFits(current, this.secretBytes, platform.hmacSha256)) {
          const repaired = await this.#confirm(this.#pointAt(step), platform);
          this.#coordinates.assertLive();
          if (repaired !== undefined) found(repaired);
        }
        const turn = tried();
        // A stop of the host ends this branch's search; the caller tells it (searchBranches).
        if (turn !== undefined) {
          const state = await turn;
          this.#coordinates.assertLive();
          if (state === "stopped") return;
        }
      }
    } finally {
      close();
      this.#active.delete(close);
    }
  }

  /** Elements that a hidden direction changes. */
  unsettledElements(): MarkedElement[] {
    const { joint } = this.#parts;
    const { hidden } = this.#directions();
    return joint.spaces.flatMap((space, share) => {
      const changed = hidden.reduce(
        (bits, direction) => bits | joint.holeChange(share, direction),
        0n,
      );
      return space
        .holesChangedBy(changed)
        .map((place) => ({ share: share + 1, position: place + 1 }));
    });
  }

  /** Every share at joint point `z`, read as an ordinary share; undefined if one does not read. */
  #readCandidate(z: bigint): ReadRepairableShare[] | undefined {
    const { joint } = this.#parts;
    const shares: ReadRepairableShare[] = [];
    for (const [share, space] of joint.spaces.entries()) {
      const values = space.valuesAt(space.particular ^ joint.holeChange(share, z));
      try {
        const read = space.reading.solvedShare(values);
        if (read === undefined) return undefined;
        shares.push(read);
      } finally {
        values.fill(0);
      }
    }
    return shares;
  }

  /** Confirms a digest match while owning active coordinates, share views and entropy buffers. */
  async #confirm(z: bigint, platform: ShareRepairPlatform): Promise<RepairedSet | undefined> {
    using point = SecretValue.bigints([z]);
    z = 0n;
    let shares: ReadRepairableShare[] | undefined;
    // Retain returned buffers for disposal while a later surplus check awaits the host.
    const entropy = new Set<Uint8Array>();
    const assertLive = () => this.#coordinates.assertLive();
    const close = () => {
      point.wipe();
      shares?.splice(0);
      for (const bytes of entropy) bytes.fill(0);
      entropy.clear();
    };
    const guarded: ShareCombiner = {
      combineShares: async (records) => {
        assertLive();
        let bytes: Uint8Array | undefined;
        try {
          bytes = await platform.combineShares(records);
          assertLive();
          entropy.add(bytes);
          return bytes;
        } catch (error) {
          bytes?.fill(0);
          throw error;
        }
      },
    };
    this.#active.add(close);
    try {
      const hiddenBits = Math.min(this.#hiddenCount, MAX_HIDDEN_TRIES_BITS);
      for (let choice = 0; choice < 2 ** hiddenBits; choice += 1) {
        shares = this.#readHiddenCandidate(point, choice);
        if (shares === undefined) continue;
        const restored = await restore(shares, guarded, assertLive);
        assertLive();
        if (restored === undefined) return undefined;
        const { mnemonic, unchecked } = restored;
        return {
          mnemonic,
          shares,
          unsettled: this.unsettledElements(),
          ...uncheckedField(unchecked),
        };
      }
      return undefined;
    } finally {
      // Successful plain shares have transferred; close only the remaining owned buffers.
      shares = undefined;
      close();
      this.#active.delete(close);
    }
  }

  #readHiddenCandidate(
    point: SecretValue<readonly bigint[]>,
    choice: number,
  ): ReadRepairableShare[] | undefined {
    const { hidden } = this.#directions();
    return this.#readCandidate(defined(point.value[0]) ^ combination(hidden, BigInt(choice)));
  }
}

export class AmbiguousMarksError extends Error {
  readonly code: ShareRepairErrorCode = "ambiguous-marks";

  constructor() {
    super(AMBIGUOUS_MARK_WIDTHS);
    this.name = "AmbiguousMarksError";
  }
}

export class MarkedReading extends Redacted implements Disposable {
  readonly #values: SecretValue<readonly number[]>;
  readonly #readBits: SecretValue<readonly (readonly number[])[]>;
  readonly #candidates: SecretValue<readonly (readonly number[])[]>;
  readonly #codes: SecretValue<readonly string[]>;
  readonly #hasReadBits: boolean;
  readonly #hasCandidates: boolean;
  readonly #codeLengths: readonly number[];
  readonly #codePrefix: boolean | undefined;
  readonly #format: ShareFormat;
  readonly #decoys: boolean;
  readonly #structure: ShareStructure;
  readonly #holes: readonly number[];

  private constructor(units: ReadingUnits, structure: ShareStructure) {
    super("MarkedReading");
    const owned: Disposable[] = [];
    try {
      this.#values = SecretValue.numbers(units.values.map((value) => value ?? 0));
      owned.push(this.#values);
      this.#readBits = SecretValue.numberLists(
        (units.readBits ?? []).map((bits) => (bits === undefined ? [] : [bits.value, bits.mask])),
      );
      owned.push(this.#readBits);
      this.#candidates = SecretValue.numberLists(
        (units.candidates ?? []).map((values) => (values === undefined ? [0] : [1, ...values])),
      );
      owned.push(this.#candidates);
      const pairs = units.codeConstraints?.pairs ?? [];
      this.#codes = SecretValue.utf16Texts(pairs.flat());
      owned.push(this.#codes);
      this.#hasReadBits = units.readBits !== undefined;
      this.#hasCandidates = units.candidates !== undefined;
      this.#codeLengths = Object.freeze(pairs.map((pair) => pair.length));
      this.#codePrefix = units.codeConstraints?.prefix;
      this.#format = units.format;
      this.#decoys = units.decoys === true;
      this.#structure = structure;
      this.#holes = Object.freeze(
        units.values.flatMap((value, index) => (value === undefined ? [index] : [])),
      );
    } catch (error) {
      for (const owner of owned) owner[Symbol.dispose]();
      throw error;
    }
  }

  /** Every supported reading; each result is independently owned and must be disposed. */
  static of(text: string): MarkedReading[] {
    const readings: MarkedReading[] = [];
    try {
      for (const { structures, ...units } of unitModels(text))
        for (const structure of structures) readings.push(new MarkedReading(units, structure));
      return readings;
    } catch (error) {
      for (const reading of readings) reading.wipe();
      throw error;
    }
  }

  /** A separate snapshot of this live reading, including all symbolic constraints. */
  copy(): MarkedReading {
    return new MarkedReading(this.#snapshot(), this.#structure);
  }

  /** Refuses work after disposal; metadata and earlier caller views are not recalled. */
  assertLive(): void {
    this.#values.assertLive();
  }

  /** The form of this reading; layout metadata remains available after disposal. */
  get format(): ShareFormat {
    return this.#format;
  }

  /** Whether complete decoy cards follow a supported prefix. */
  get withDecoys(): boolean {
    return this.#decoys;
  }

  /** The number of bits per unit of this form. */
  get unitBits(): number {
    return SHARE_UNITS[this.#format].unitBits;
  }

  /** A fresh unit-value snapshot, undefined at marks; refused after disposal. */
  get values(): readonly (number | undefined)[] {
    return Object.freeze(
      this.#values.value.map((value, index) => (this.#holes.includes(index) ? undefined : value)),
    );
  }

  /** The borrowed public byte layout; its evaluator receives all secret values as parameters. */
  get structure(): ShareStructure {
    return this.#structure;
  }

  /** A fresh snapshot of partial unit bits, if present; refused after disposal. */
  get readBits(): readonly (ReadBits | undefined)[] | undefined {
    this.assertLive();
    if (!this.#hasReadBits) return undefined;
    return Object.freeze(
      this.#readBits.value.map((bits) =>
        bits.length === 0
          ? undefined
          : Object.freeze({ value: defined(bits[0]), mask: defined(bits[1]) }),
      ),
    );
  }

  /** Fresh candidate lists for partial units, if present; refused after disposal. */
  get candidates(): readonly (readonly number[] | undefined)[] | undefined {
    this.assertLive();
    if (!this.#hasCandidates) return undefined;
    // A separate presence flag preserves an admitted empty list as distinct from no constraint.
    return Object.freeze(
      this.#candidates.value.map((values) =>
        values[0] === 0 ? undefined : Object.freeze(values.slice(1)),
      ),
    );
  }

  /** Marked unit places, counted from 0, in their bit order; layout metadata. */
  get holes(): readonly number[] {
    return this.#holes;
  }

  /** The number of unknown bits, marked unit count times unit width. */
  get unknownBits(): number {
    return this.#holes.length * this.unitBits;
  }

  #shift(order: number): bigint {
    return BigInt(order * this.unitBits);
  }

  /** The bit mask of marked unit `order`, counted from 0 among holes. */
  unitMask(order: number): bigint {
    return ((1n << BigInt(this.unitBits)) - 1n) << this.#shift(order);
  }

  /** Caller-owned unit values with `bits` at the marks; refused after disposal. */
  valuesAt(bits: bigint): number[] {
    const values = this.zeroFilled();
    this.#holes.forEach((hole, order) => {
      // The mask admits one unit only, at most 24 bits, so this conversion is exact.
      values[hole] = Number((bits & this.unitMask(order)) >> this.#shift(order));
    });
    return values;
  }

  /** Caller-owned values with every marked unit set to zero; refused after disposal. */
  zeroFilled(): number[] {
    return [...this.#values.value];
  }

  /** Independent reading with chosen unit values added as full-width equations. */
  withValues(chosen: ReadonlyMap<number, number>): MarkedReading {
    const units = this.#snapshot();
    const mask = 2 ** this.unitBits - 1;
    const readBits = units.values.map((_, place) => {
      const value = chosen.get(place);
      return value === undefined ? units.readBits?.[place] : { value, mask };
    });
    return new MarkedReading({ ...units, readBits }, this.#structure);
  }

  /** Whether changing unit `place`, counted from 0, reaches the share's metadata bytes. */
  reachesMetadata(place: number): boolean {
    const values = this.zeroFilled();
    let before: Uint8Array | undefined;
    try {
      before = this.#structure.evaluate(values).payload;
      for (let bit = 0; bit < this.unitBits; bit += 1) {
        const flipped = [...values];
        let after: Uint8Array | undefined;
        try {
          flipped[place] = defined(values[place]) ^ (1 << bit);
          after = this.#structure.evaluate(flipped).payload;
          for (let byte = 0; byte < SHARE_METADATA_BYTES; byte += 1)
            if (after[byte] !== before[byte]) return true;
        } finally {
          after?.fill(0);
          flipped.fill(0);
        }
      }
      return false;
    } finally {
      before?.fill(0);
      values.fill(0);
    }
  }

  /** Independent readings for all candidate choices; even an empty choice returns an owned copy. */
  choicesAt(places: readonly number[]): MarkedReading[] {
    const { candidates } = this;
    const tried = places.filter((place) => candidates?.[place] !== undefined);
    if (tried.length === 0) return [this.copy()];
    const picks = defined(everyPick(tried.map((place) => defined(defined(candidates)[place]))));
    const readings: MarkedReading[] = [];
    try {
      for (const values of picks)
        readings.push(
          this.withValues(new Map(tried.map((place, index) => [place, defined(values[index])]))),
        );
      return readings;
    } catch (error) {
      for (const reading of readings) reading.wipe();
      throw error;
    } finally {
      for (const values of picks) values.fill(0);
    }
  }

  /** Candidate unit places, counted from 0, and the number of values of each. */
  candidateCounts(): { readonly place: number; readonly count: number }[] {
    return (this.candidates ?? []).flatMap((values, place) =>
      values === undefined ? [] : [{ place, count: values.length }],
    );
  }

  /** A caller-owned share snapshot if values fit the reading and ordinary reader, else undefined. */
  solvedShare(values: readonly number[]): ReadRepairableShare | undefined {
    this.assertLive();
    if (!this.#fits(values)) return undefined;
    const units = SHARE_UNITS[this.#format];
    let read;
    try {
      read = readShare(units.text(values));
    } catch {
      return undefined;
    }
    if (read.format !== this.#format) return undefined;
    const filled = this.#holes.map((index) => ({
      position: index + 1,
      value: units.unitText(defined(values[index])),
    }));
    return { ur: read.ur, format: read.format, repaired: filled.length > 0, filled };
  }

  #constraints(): ReadingCodeConstraints | undefined {
    this.assertLive();
    if (this.#codePrefix === undefined) return undefined;
    const codes = this.#codes.value;
    let start = 0;
    const pairs = this.#codeLengths.map((length) => {
      const pair = codes.slice(start, start + length);
      start += length;
      return pair;
    });
    return { pairs, prefix: this.#codePrefix };
  }

  #snapshot(): ReadingUnits {
    const values = this.values;
    const readBits = this.readBits;
    const candidates = this.candidates;
    const codeConstraints = this.#constraints();
    return {
      format: this.#format,
      values,
      decoys: this.#decoys,
      ...(readBits === undefined ? {} : { readBits }),
      ...(candidates === undefined ? {} : { candidates }),
      ...(codeConstraints === undefined ? {} : { codeConstraints }),
    };
  }

  #fits(values: readonly number[]): boolean {
    const candidates = this.candidates;
    if (
      candidates !== undefined &&
      !candidates
        .slice(0, values.length)
        .every((allowed, place) => allowed?.includes(defined(values[place])) ?? true)
    )
      return false;
    const constraints = this.#constraints();
    if (constraints === undefined) return true;
    const pairs = constraints.prefix
      ? constraints.pairs.slice(0, values.length)
      : constraints.pairs;
    return pairs.every((pair, index) => {
      const written = defined(
        SHARE_UNITS[this.#format].unitText(defined(values[index])).match(CODE_POINT_TEXT),
      );
      return pair.every((code, half) =>
        constraints.prefix
          ? wholeMark(code) || fitsPattern(code, defined(written[half]))
          : code === "?" || code === written[half],
      );
    });
  }

  /** An independently owned solution space; the caller disposes it. */
  space(): ReadingSpace | undefined {
    return ReadingSpace.solve(this);
  }

  /** Uses a temporary space synchronously and disposes it on success or failure. */
  withSpace<T>(use: (space: ReadingSpace | undefined) => T): T {
    return ReadingSpace.use(this, use);
  }

  /** Overwrites owned buffers as far as the runtime allows, without affecting derived owners. */
  wipe(): void {
    this.#values.wipe();
    this.#readBits.wipe();
    this.#candidates.wipe();
    this.#codes.wipe();
  }

  /** Ends this reading's lifetime; idempotent. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class ReadingSpace extends Redacted implements Disposable {
  readonly #reading: MarkedReading;
  readonly #rank: number;
  readonly #coordinates: SecretValue<readonly bigint[]>;
  readonly #payload: Uint8Array;
  readonly #payloadDeltas: readonly Uint8Array[];

  private constructor(
    reading: MarkedReading,
    solved: {
      readonly rank: number;
      readonly particular: bigint;
      readonly free: readonly bigint[];
    },
    payload: Uint8Array,
    payloadDeltas: readonly Uint8Array[],
  ) {
    super("ReadingSpace");
    const deltas = Object.freeze([...payloadDeltas]);
    this.#coordinates = SecretValue.bigints([solved.particular, ...solved.free]);
    this.#reading = reading;
    this.#rank = solved.rank;
    this.#payload = payload;
    this.#payloadDeltas = deltas;
  }

  /** Solves a borrowed reading into an independent owner; undefined when no values fit. */
  static solve(input: MarkedReading): ReadingSpace | undefined {
    const reading = input.copy();
    const arrays: Uint8Array[] = [];
    let transferred = false;
    try {
      const { holes, unitBits, unknownBits, readBits } = reading;
      const at = (bits: bigint) => {
        const values = reading.valuesAt(bits);
        let evaluated: ReturnType<ShareStructure["evaluate"]> | undefined;
        try {
          evaluated = reading.structure.evaluate(values);
          if (readBits === undefined) return evaluated;
          const read = BitFields.of(
            holes.map((hole) => {
              const bitsRead = readBits[hole];
              const change =
                bitsRead === undefined
                  ? 0
                  : (defined(values[hole]) ^ bitsRead.value) & bitsRead.mask;
              return [change, unitBits] as const;
            }),
          );
          return { ...evaluated, residual: (evaluated.residual << BigInt(unknownBits)) | read };
        } catch (error) {
          evaluated?.payload.fill(0);
          throw error;
        } finally {
          values.fill(0);
        }
      };
      const residualAt = (bits: bigint): bigint => {
        const { residual, payload } = at(bits);
        payload.fill(0);
        return residual;
      };
      const { value: baseline, columns } = linearize(residualAt, 0n, unitVectors(unknownBits));
      let solved: ReturnType<typeof solve>;
      try {
        solved = solve(columns, baseline);
      } finally {
        columns.fill(0n);
      }
      if (solved === undefined) return undefined;
      const payload = at(solved.particular).payload;
      arrays.push(payload);
      const payloadDeltas: Uint8Array[] = [];
      for (const direction of solved.free) {
        const delta = at(solved.particular ^ direction).payload;
        arrays.push(delta);
        xorInto(delta, payload);
        payloadDeltas.push(delta);
      }
      const space = new ReadingSpace(reading, solved, payload, payloadDeltas);
      transferred = true;
      return space;
    } finally {
      if (!transferred) {
        reading.wipe();
        for (const array of arrays) array.fill(0);
      }
    }
  }

  /** Uses the space synchronously; its complete owner is disposed even when use throws. */
  static use<T>(reading: MarkedReading, use: (space: ReadingSpace | undefined) => T): T {
    using space = ReadingSpace.solve(reading);
    return use(space);
  }

  /** Refuses secret reads after this space is disposed. */
  assertLive(): void {
    this.#coordinates.assertLive();
  }

  /** Borrowed child reading, valid until this space ends; copy it for an independent lifetime. */
  get reading(): MarkedReading {
    this.assertLive();
    return this.#reading;
  }

  /** The number of marked bits; layout metadata remains readable after disposal. */
  get unknownBits(): number {
    return this.#reading.unknownBits;
  }

  /** The rank of the equations; layout metadata remains readable after disposal. */
  get rank(): number {
    return this.#rank;
  }

  /** One exact affine solution; refused after disposal. */
  get particular(): bigint {
    return defined(this.#coordinates.value[0]);
  }

  /** A fresh exact basis snapshot; refused after disposal. */
  get basis(): readonly bigint[] {
    return Object.freeze(this.#coordinates.value.slice(1));
  }

  /** Marked unit places, counted from 0; layout metadata. */
  get holes(): readonly number[] {
    return this.#reading.holes;
  }

  /** The mask of marked unit `order`, counted from 0; layout metadata. */
  unitMask(order: number): bigint {
    return this.#reading.unitMask(order);
  }

  /** Caller-owned unit values for exact marked bits; refused after disposal. */
  valuesAt(bits: bigint): number[] {
    this.assertLive();
    return this.#reading.valuesAt(bits);
  }

  /** Marked unit places that `change` touches, counted from 0. */
  holesChangedBy(change: bigint): number[] {
    return this.holes.filter((_, order) => (change & this.unitMask(order)) !== 0n);
  }

  /** New caller-owned payload bytes for basis choice `own`; wipe them after use. */
  payloadAt(own: bigint): Uint8Array {
    this.assertLive();
    const payload = Uint8Array.from(this.#payload);
    this.#payloadDeltas.forEach((delta, j) => {
      if ((own >> BigInt(j)) & 1n) xorInto(payload, delta);
    });
    return payload;
  }

  /** A fixed payload byte, or undefined if a solution changes it; refused after disposal. */
  fixedPayloadByte(index: number): number | undefined {
    this.assertLive();
    return this.#payloadDeltas.every((delta) => delta[index] === 0)
      ? this.#payload[index]
      : undefined;
  }

  /**
   * Borrowed payload/delta buffers for legacy cleanup observations, still available after wipe.
   * Wiping these arrays alone does not end the reading/coordinate lifetime: dispose this owner.
   */
  secretArrays(): Uint8Array[] {
    return [this.#payload, ...this.#payloadDeltas];
  }

  /** Overwrites owned buffers and ends the child reading; leaves the caller's input live. */
  wipe(): void {
    this.#coordinates.wipe();
    this.#reading.wipe();
    this.#payload.fill(0);
    for (const array of this.#payloadDeltas) array.fill(0);
  }

  /** Ends this space's lifetime; shared spaces belong to the containing plan, not each branch. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export type ReportLine =
  | {
      readonly kind: "status";
      readonly label: string;
      readonly value: string;
      readonly good: boolean;
    }
  | { readonly kind: "hint" | "notice" | "warning"; readonly text: string }
  | { readonly kind: "more"; readonly anchor: string };

export interface UnitModel extends ReadingUnits {
  readonly structures: readonly ShareStructure[];
}

export class ShareVariantsError extends Error {
  readonly code: ShareRepairErrorCode = "share-variants";

  readonly places: readonly number[];

  constructor(
    readonly count: number,
    places: readonly number[],
  ) {
    super(
      `${count} shares fit the marked elements ${places.join(", ")}. Use another copy of this share, or another share.`,
    );
    this.places = Object.freeze([...places]);
  }
}

export type ShareTrouble =
  | { readonly kind: "unreadable"; readonly place: number; readonly message: string }
  | { readonly kind: "odd"; readonly place: number; readonly message: string }
  | { readonly kind: "few"; readonly message: string }
  | { readonly kind: "refused"; readonly message: string };

export type CompleteOutcome =
  | {
      readonly kind: "complete";
      readonly set: RepairedSet;
      readonly secretBytes: number;
      /**
       * The places of the set's shares among those typed, copies left out: those of the shares as
       * they were when the restore began, so that a host that changes the input while it awaits
       * the restore still gets the places of the set restored (AUD-014-API004).
       */
      readonly places: readonly number[];
    }
  | SharesTrouble;

export type EachRepair =
  | { readonly kind: "repaired"; readonly shares: readonly ReadRepairableShare[] }
  | {
      readonly kind: "unreadable";
      readonly place: number;
      readonly message: string;
      readonly cause: Error;
    }
  | {
      readonly kind: "variants";
      readonly place: number;
      readonly variants: readonly ReadRepairableShare[];
      readonly message: string;
    };

export type CheckedExport =
  | { readonly kind: "written"; readonly written: ShareExport }
  /** Every share has an element that nothing settles: each is left out. */
  | { readonly kind: "none"; readonly written: ShareExport }
  /** Shares repaired each on its own may be of several sets, or the same member twice. */
  | (SharesTrouble & { readonly written: ShareExport });

export class ShareInput implements Disposable {
  #texts = SecretValue.utf16Texts([]);
  #places: readonly number[] = [];
  #nextPlace = 1;
  readonly #decodeEntry: string;

  /**
   * `decodeEntry` names where the host reads an encoded seed phrase, which a seed phrase typed in
   * place of a share is sent to: "Decode numbers, codes or colors back into a seed phrase" in the
   * command line's menu, "The Decode tab" on a page.
   */
  constructor(options: { readonly decodeEntry: string }) {
    if (typeof options?.decodeEntry !== "string" || options.decodeEntry.trim() === "")
      throw ERRORS.create("share-input-name-host-s-reader-seed-phrase", []);
    this.#decodeEntry = options.decodeEntry;
  }

  get #shares(): TypedShare[] {
    return this.#texts.value.map((text, index) =>
      Object.freeze({ place: defined(this.#places[index]), text }),
    );
  }

  set #shares(shares: readonly TypedShare[]) {
    this.#texts.assertLive();
    const texts = SecretValue.utf16Texts(shares.map((share) => share.text));
    this.#texts.wipe();
    this.#texts = texts;
    this.#places = shares.map((share) => share.place);
  }

  /**
   * The parts of a share file or paste, with empty lines left out and wrapped shares joined.
   * Unreadable parts stay in place: the reader must name them, never silently drop them. Decode
   * uses the same boundaries before deciding whether the text holds shares or phrase codes.
   */
  static partsOfText(text: string): string[] {
    const parts = text
      .split(SHARE_SEPARATORS)
      .map((part) => part.trim())
      .filter(Boolean);
    if (parts.length === 0) return [];
    // Bounds the work below: wrapped or not, the parts make no more shares than a set may have.
    assertShareCount(Math.ceil(parts.length / MAX_WRAPPED_LINES));
    const shares = joinWrapped(parts);
    assertShareCount(shares.length);
    return shares;
  }

  /**
   * `message` of a share after "Share N" and `joint`, such as "Share 2 cannot be read: unknown …".
   * Its first letter is made small, unless it begins an abbreviation such as SSKR.
   */
  static aboutShare(place: number, joint: string, message: string): string {
    return afterPlace("Share", place, message, joint);
  }

  /**
   * The first share of `shares` that does not belong with the others, for shares that need no
   * quorum, such as those written again by an export. A copy of a share is no problem.
   */
  static looseSetTrouble(shares: readonly PlacedShare[]): ShareTrouble | undefined {
    return setTrouble(withoutCopies(shares).map(withInfo));
  }

  /**
   * Why complete shares cannot be restored together, as sskr-combine says it before it tries:
   * shares that do not belong together (setTrouble) and, unless `more` are still to come, too
   * few for the quorum they record (fewTrouble). Copies are left out first. The restore here and
   * the backup check both ask it.
   */
  static completeSetProblem(shares: readonly PlacedShare[], more = false): string | undefined {
    const read = withoutCopies(shares).map(withInfo);
    if (read.length === 0) return undefined;
    return (setTrouble(read) ?? (more ? undefined : fewTrouble(read)))?.message;
  }

  /**
   * The shares of `shares` that copy an earlier one exactly (the same UR), each with the place of
   * the first and a note: a copy adds nothing to a restore, so it is left out and used once. The
   * restore here and the backup check (core/backup-check.ts) both apply this rule.
   */
  static copiesOf(shares: readonly PlacedShare[]): ShareCopy[] {
    return copiesAmong(shares).map((copy) => ({
      ...copy,
      message: `Share ${copy.place} is a copy of share ${copy.of}: it is used once.`,
    }));
  }

  /** The shares typed, each with its place; a copy, so that only this object's changes count. */
  get list(): readonly TypedShare[] {
    return Object.freeze([...this.#shares]);
  }

  /** The texts, in the order typed, as the share functions take them. */
  texts(): string[] {
    return this.#shares.map((share) => share.text);
  }

  /** The place of each share, by its index in texts(). */
  places(): number[] {
    return this.#shares.map((share) => share.place);
  }

  /** Whether an element of a share is marked with ? as unreadable. */
  get marked(): boolean {
    return this.#shares.some((share) => isMarked(share.text));
  }

  /** Whether a share was typed at `place`, and is not left out. */
  has(place: number): boolean {
    return this.#shares.some((share) => share.place === place);
  }

  /**
   * The shares in a text, typed, pasted or read from a file: split at ; and at line breaks, as a
   * page's field holds one share per line, with each share that a paste or a narrow column wrapped
   * over lines joined again (wrappedShare); none for a text without one. An empty part, from a ; at
   * the end or two in a row, is no share and is passed over. A seed phrase, also one word per line,
   * is refused as one: `subject` names the text in that message, "This is" or "The file holds".
   */
  sharesOfText(text: string, subject = "This is"): string[] {
    this.#texts.assertLive();
    const shares = ShareInput.partsOfText(text);
    if (shares.length === 0) return [];
    // Looked for only when nothing reads as a share: a share in word numbers, wrapped or not, may
    // have as many numbers as a phrase has words.
    if (!shares.some(shareOrMarked)) {
      const kind = phraseKind(shares.join(" "));
      if (kind !== undefined)
        throw ERRORS.create("shares-text-refused", [this.#notShareMessage(kind, subject)]);
    }
    return shares;
  }

  /**
   * The shares of one answer (sharesOfText), at least one, checked to fit in a set: alone, or
   * `adding` them to those typed.
   */
  sharesOfAnswer(answer: string, adding = false): string[] {
    const shares = this.sharesOfText(answer);
    if (shares.length === 0) throw ERRORS.create("type-at-least-one-share", []);
    assertShareCount((adding ? this.#shares.length : 0) + shares.length);
    return shares;
  }

  /** Adds shares after those typed, each at the next place; adding none changes nothing. */
  add(texts: readonly string[]): void {
    this.#texts.assertLive();
    if (texts.length === 0) return;
    const previous = this.#shares;
    assertShareCount(previous.length + texts.length);
    this.#shares = [
      ...previous,
      ...texts.map((text, index) => ({ place: this.#nextPlace + index, text })),
    ];
    this.#nextPlace += texts.length;
  }

  /** Takes `texts` in place of every share typed before, at places from 1. */
  replaceAll(texts: readonly string[]): void {
    this.#texts.assertLive();
    assertShareCount(texts.length);
    this.#shares = texts.map((text, index) => ({ place: index + 1, text }));
    this.#nextPlace = texts.length + 1;
  }

  /** Takes `text` for the share at `place`, which keeps its place. */
  replace(place: number, text: string): void {
    if (!this.has(place)) throw ERRORS.create("no-share-was-typed-at-place", [`${place}`]);
    this.#shares = this.#shares.map((share) =>
      share.place === place ? Object.freeze({ place, text }) : share,
    );
  }

  /** Leaves out the share at `place`; the others keep their places. */
  leaveOut(place: number): void {
    this.#shares = this.#shares.filter((share) => share.place !== place);
  }

  /**
   * Why a share cannot be used even before the others are looked at, or undefined: a share without
   * ? must read as a share in one of its forms; one with ? may hold only as many marks as a joint
   * repair takes (planJointRepair), which tells later whether the rest of it fits.
   */
  readProblem(place: number, text: string): string | undefined {
    this.#texts.assertLive();
    if (isMarked(text)) {
      const limit = jointMarkLimitProblem(place, text);
      if (limit !== undefined) return limit;
      const problem = markProblem(text);
      return problem === undefined ? undefined : afterPlace("Share", place, problem);
    }
    try {
      readShare(text);
      return undefined;
    } catch (error) {
      const message = refusalMessage(error);
      const kind = phraseKind(text);
      return kind === undefined
        ? ShareInput.aboutShare(place, " cannot be read: ", message)
        : this.#notShareMessage(kind, `Share ${place} is`);
    }
  }

  /** The first share typed that cannot be read (readProblem), or undefined. */
  firstUnreadable(): ShareTrouble | undefined {
    for (const { place, text } of this.#shares) {
      const trouble = this.#unreadable(place, text);
      if (trouble !== undefined) return trouble;
    }
    return undefined;
  }

  /**
   * The trouble of the share typed at `place` when it cannot be read (readProblem), named by its
   * place; undefined when it can. Every reader of the typed shares refuses one so
   * (AUD-012-ARC010).
   */
  #unreadable(place: number, text: string): ShareTrouble | undefined {
    const message = this.readProblem(place, text);
    return message === undefined ? undefined : { kind: "unreadable", place, message };
  }

  /**
   * The first problem of complete shares written again by an export, which needs no quorum: each
   * must be read, and all must be of one set; copies of a share are kept, to be shown as typed and
   * saved once.
   */
  looseTrouble(): ShareTrouble | undefined {
    const read = this.#readAll();
    return Array.isArray(read) ? ShareInput.looseSetTrouble(read) : read;
  }

  /**
   * Restores complete shares: each is read, copies are left out (and returned, with a note), the
   * set is checked (setTrouble, fewTrouble), and its phrase restored, every share checked against
   * it (ShareSet.restore). When they do not agree, the share without which the others restore a
   * phrase is named: each is left out once.
   */
  async restoreComplete(
    platform: ShareCombiner,
  ): Promise<{ readonly outcome: CompleteOutcome; readonly copies: readonly ShareCopy[] }> {
    const read = this.#readAll();
    if (!Array.isArray(read)) return { outcome: { kind: "trouble", trouble: read }, copies: [] };
    const copies = this.#dropCopies(read);
    const distinct = read.filter((share) => this.has(share.place));
    const trouble = setTrouble(distinct) ?? fewTrouble(distinct);
    if (trouble !== undefined) return { outcome: { kind: "trouble", trouble }, copies };
    // Taken before the restore is awaited: the host may change the input meanwhile.
    const outcome = await this.#restoreChecked(distinct, this.texts(), platform);
    this.#texts.assertLive();
    return { outcome, copies };
  }

  /**
   * The complete shares as one set to write again: no phrase is restored and no quorum is needed.
   * A share that cannot be read, or shares that are not of one set, are refused.
   */
  rewritten(): RewrittenShares {
    const trouble = this.looseTrouble();
    if (trouble !== undefined) return { kind: "trouble", trouble };
    const shares = this.texts().map(unrepairedShare);
    return { kind: "set", set: { shares, unsettled: [] } };
  }

  /**
   * The shares of `set` to write again, named by `places`, in `form` or their own: a share that
   * nothing settles is left out, and shares repaired each on its own must still be of one set
   * (looseSetTrouble).
   */
  static checkedExport(
    set: RepairedShares,
    places: readonly number[],
    form: ShareFormat | undefined,
  ): CheckedExport {
    const written = ShareExport.of(set, places, form);
    try {
      if (written.shown.length === 0) return { kind: "none", written };
      const trouble = ShareInput.looseSetTrouble(written.members);
      if (trouble !== undefined) return { kind: "trouble", written, trouble };
      return { kind: "written", written };
    } catch (error) {
      written.wipe();
      throw error;
    }
  }

  repairEach(): EachRepair {
    const shares: ReadRepairableShare[] = [];
    for (const { place, text } of this.#shares) {
      try {
        const variants = repairCandidates(text);
        if (variants.length > 1)
          return {
            kind: "variants",
            place,
            variants,
            message: `Share ${place} fits ${variants.length} ways, so nothing is saved: use another copy of it, or more shares.`,
          };
        shares.push(defined(variants[0]));
      } catch (error) {
        // Narrowed here, not by refusalMessage: the result keeps the Error as its cause.
        if (!(error instanceof Error)) throw error;
        return {
          kind: "unreadable",
          place,
          message: ShareInput.aboutShare(place, ": ", error.message),
          cause: error,
        };
      }
    }
    return { kind: "repaired", shares };
  }

  /**
   * The problem that an assessment of marked shares names, or undefined when they can be searched.
   * The assessment is of these shares, planned with their places (ShareRestore.read), so that its
   * reason names each share as it was typed. `places` are those it was planned with, which a host
   * that changed the input while the assessment ran no longer has (AUD-014-API004).
   */
  assessmentTrouble(
    assessment: JointAssessment,
    places: readonly number[] = this.places(),
  ): ShareTrouble | undefined {
    this.#texts.assertLive();
    if (assessment.reason === undefined) return undefined;
    // A share that no reading fits is typed again or left out, by its place.
    if (assessment.unfit !== undefined)
      return {
        kind: "unreadable",
        place: defined(places[assessment.unfit - 1]),
        message: assessment.reason,
      };
    return {
      kind: assessment.verdict === "not-enough" ? "few" : "refused",
      message: assessment.reason,
    };
  }

  /**
   * The one line for a seed phrase typed where a share was asked for: what it is and which entry
   * reads it, without repeating it. `subject` is "This is", "The file holds" or "Share N is".
   */
  #notShareMessage(kind: "words" | "encoded", subject: string): string {
    return kind === "words"
      ? `${subject} a seed phrase in words, not a Shamir share: ${this.#decodeEntry} reads a masked one.`
      : `${subject} an encoded seed phrase, not a Shamir share: ${this.#decodeEntry} reads it.`;
  }

  /**
   * Reads every complete share; no share at all, or the first that cannot be read, is the trouble.
   * An input that is empty, as it starts and once every share is left out, is "few": more shares
   * are needed (AUD-014-API009).
   */
  #readAll(): ReadShare[] | ShareTrouble {
    const count = shareCountProblem(this.#shares.length);
    if (count !== undefined) return { kind: "few", message: count };
    const trouble = this.firstUnreadable();
    if (trouble !== undefined) return trouble;
    return this.#shares.map(({ place, text }) => {
      using share = Share.read(text);
      return { place, ur: share.ur, info: share.info };
    });
  }

  /** Leaves out each share typed again as an earlier one (copiesOf). */
  #dropCopies(read: readonly ReadShare[]): ShareCopy[] {
    const copies = ShareInput.copiesOf(read);
    for (const copy of copies) this.leaveOut(copy.place);
    return copies;
  }

  /**
   * The phrase of `read`, typed as `texts`, checked as a set before; or the share named as the one
   * that is wrong. Bound to `read` and `texts` alone, never to the input as it is after an await.
   */
  async #restoreChecked(
    read: readonly ReadShare[],
    texts: readonly string[],
    platform: ShareCombiner,
  ): Promise<CompleteOutcome> {
    const places = read.map((share) => share.place);
    try {
      using set = await ShareSet.restore(texts, platform, places);
      this.#texts.assertLive();
      return {
        kind: "complete",
        set: set.toRepairedSet(),
        secretBytes: defined(read[0]).info.secretLength,
        places,
      };
    } catch (error) {
      this.#texts.assertLive();
      const message = refusalMessage(error);
      const fits: number[] = [];
      for (const [index, share] of read.entries()) {
        try {
          using _otherSet = await ShareSet.restore(
            texts.filter((_, other) => other !== index),
            platform,
          );
          this.#texts.assertLive();
          fits.push(share.place);
        } catch (other) {
          this.#texts.assertLive();
          refusalMessage(other);
        }
      }
      if (fits.length === 1)
        return {
          kind: "trouble",
          trouble: {
            kind: "odd",
            place: defined(fits[0]),
            message: misfitMessage(defined(fits[0])),
          },
        };
      // The share set names each share by the place it was typed at.
      return { kind: "trouble", trouble: { kind: "refused", message } };
    }
  }

  /** Ends retained typed shares; replacements release their previous storage at once. */
  wipe(): void {
    this.#texts.wipe();
    this.#places = [];
  }

  /** Ends this input after all awaited restores and any caller-owned snapshots are complete. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export interface ShareRepairPlatform extends ShareCombiner {
  /**
   * HMAC-SHA256 of `message` under `key`. Synchronous: the search calls it for every try. Returns
   * a fresh array of the 32 bytes of the MAC, which the caller owns and may wipe once it has
   * compared it; never storage that the host reuses or a view of `key` or `message`, which stay
   * the caller's and are not changed.
   */
  readonly hmacSha256: (key: Uint8Array, message: Uint8Array) => Uint8Array;
}

export interface ShareSplitPlatform extends ShareCombiner {
  /**
   * Shares of one group that split `secret`, `threshold` of `count` needed, as UR records, from
   * the host's SSKR library; `seed` (SEED_BYTES of fresh randomness) seeds its random numbers.
   * The library may wipe `seed`; its caller wipes it too.
   */
  readonly createShares: (
    secret: Uint8Array,
    threshold: number,
    count: number,
    seed: Uint8Array,
  ) => Promise<string[]>;
}

