    threshold: number,
    count: number,
    seed: Uint8Array,
  ) => Promise<string[]>;

supplements.declaration:
export type AssessmentWatch = <T>(
  step: (signal: AbortSignal | undefined) => Promise<T>,
) => Promise<T>;

export interface RestoreRun extends SearchRun {
  readonly onProgress?: ((progress: RestoreProgress) => void) | undefined;
}

export type SharesRead =
  | (SharesTrouble & {
      /** The notes of copies left out, or the report of marked shares, said with the trouble. */
      readonly lines: readonly ReportLine[];
    })
  | {
      readonly kind: "complete";
      readonly set: RepairedSet;
      readonly secretBytes: number;
      /** The places of the set's shares among those typed, copies left out. */
      readonly places: readonly number[];
      /** The notes of copies left out. */
      readonly lines: readonly ReportLine[];
      /** The warning that a share took no part in the check of the set, if one did not. */
      readonly unchecked?: string | undefined;
    }
  | MarkedShares
  /** The host stopped the assessment of marked shares (CORE-22): nothing is planned. */
  | { readonly kind: "stopped"; readonly lines: readonly ReportLine[] };

export interface ShareRestoreRequest extends RestoreRun {
  /** How far a search goes without the person's yes. */
  readonly limits?: SearchLimits | undefined;
  readonly input: ShareInput;
  readonly mode: ShareMode;
  /** The dates of a Seedshift phrase, which may hold ?; none without Seedshift. */
  readonly dates?: DatesAnswer | undefined;
  /** Compares each phrase with the wallet; without it every phrase is kept. */
  readonly walletCheck?: WalletCheck | undefined;
  /** Matches of each date search kept for a candidate list; none by default. */
  readonly keep?: number | undefined;
  /** Whether the person said yes to the long search that a question announced. */
  readonly confirmed: boolean;
}

export interface RestoredPhrase extends UnmaskedPhrase {
  /** The phrase the shares hold: the seed phrase, or its Seedshift mask. */
  readonly held: string;
  /** What a repair filled in where ? marked an element, share by share. */
  readonly repairs: readonly ShareRepairs[];
  /** The backup in the form its shares were written in, where it is not the phrase itself. */
  readonly backup?: SetBackup | undefined;
}

export type RestoredPhrases =
  | PhrasesFound
  /** The dates are more than a set's phrase takes. */
  | { readonly kind: "dates"; readonly message: string }
  /** No phrase is the wallet's (ShareSet.walletMismatch). */
  | { readonly kind: "mismatch"; readonly message: string }
  /** The host stopped the date search: no phrase is told (CORE-22). */
  | { readonly kind: "stopped" };

export type ShareStop =
  | {
      readonly kind: "trouble";
      readonly message: string;
      readonly lines: readonly ReportLine[];
    }
  | {
      readonly kind: "question";
      readonly question: string;
      readonly lines: readonly ReportLine[];
    }
  /** The host stopped the assessment or a search (CORE-22): nothing is told. */
  | { readonly kind: "stopped"; readonly lines: readonly ReportLine[] };

export type SearchedSets =
  | { readonly kind: "sets"; readonly sets: RepairedSet[]; readonly notes: readonly string[] }
  | { readonly kind: "none"; readonly message: string }
  /** The host stopped the search (RestoreRun.signal): no set is told (CORE-22). */
  | { readonly kind: "stopped" };

export type ShareRestoreOutcome =
  | ShareStop
  | FewShares
  | (PhrasesFound & {
      readonly places: readonly number[];
      readonly lines: readonly ReportLine[];
      readonly notes: readonly string[];
    });

export type ShareExportDecision<Result extends PhrasesFound | { readonly kind: "few" }> =
  | { readonly kind: "each"; readonly few: Extract<Result, { readonly kind: "few" }> }
  | { readonly kind: "variants"; readonly found: Extract<Result, PhrasesFound> }
  | {
      readonly kind: "set";
      readonly found: Extract<Result, PhrasesFound>;
      readonly set: RepairedSet;
    }
  | { readonly kind: "trouble"; readonly message: string };

export interface ShareRepairRequest extends Omit<ShareRestoreRequest, "keep"> {
  /** The form every share is written in; without it each keeps its own. */
  readonly form?: ShareFormat | undefined;
  /**
   * The master fingerprint of a phrase with an empty passphrase, for sets that fit several ways.
   */
  readonly fingerprintOf: (mnemonic: string) => string;
}

export type ShareRepairOutcome =
  | ShareStop
  | {
      readonly kind: "shares";
      readonly shares: readonly RepairedShare[];
      /** The one form every share is written in; undefined when they keep different forms. */
      readonly form: ShareFormat | undefined;
      readonly repairs: readonly ShareRepairs[];
      readonly lines: readonly ReportLine[];
      readonly notes: readonly string[];
    }
  | {
      readonly kind: "variants";
      readonly message: string;
      readonly variants: readonly ShareVariant[];
      readonly lines: readonly ReportLine[];
    };

export class ShareSet extends Redacted implements Disposable {
  readonly #mnemonic: SecretValue<string>;
  readonly #shares: ShareValues;
  readonly #unsettled: readonly MarkedElement[];
  readonly #unchecked: readonly number[] | undefined;
  readonly #infos: readonly ShareInfo[];

  private constructor(set: RepairedSet) {
    super("ShareSet");
    if (set.shares.length === 0) throw ERRORS.create("share-set-at-least-one-share", []);
    // Snapshot the admitted fields only; borrowed objects may contain extra private material.
    const copy = frozenSet(set);
    this.#infos = copy.shares.map((share) => {
      using read = Share.read(share.ur);
      return read.info;
    });
    const mnemonic = SecretValue.text(copy.mnemonic);
    try {
      this.#shares = new ShareValues(copy.shares);
      this.#mnemonic = mnemonic;
      this.#unsettled = copy.unsettled;
      this.#unchecked = copy.unchecked;
    } catch (error) {
      mnemonic.wipe();
      throw error;
    }
  }

  /**
   * Restores complete shares, each in any form MnemoCode writes, and checks every share given
   * against the phrase (restoreCompleteShares). A share that does not fit is refused by its place
   * in `places`, by its index among `records`; by that index, counted from 1, without them.
   */
  static async restore(
    records: readonly string[],
    platform: ShareCombiner,
    places?: readonly number[],
  ): Promise<ShareSet> {
    assertShareCount(records.length);
    const shares = records.map(unrepairedShare);
    const { mnemonic, unchecked } = await restoreCompleteShares(
      shares.map((share) => share.ur),
      platform,
      places,
    );
    return new ShareSet({
      mnemonic,
      shares,
      unsettled: [],
      ...uncheckedField(unchecked),
    });
  }

  /**
   * Restores the one phrase that `records` hold, in any form, with elements marked with ? where
   * unreadable, all with `platform`: complete shares by its SSKR library, marked ones assessed and
   * searched with it (JointRepair). A repair that needs a long search, or that more than one
   * phrase passes, is refused; a host that shows the assessment and asks first uses JointRepair
   * and ShareSet.of for each phrase found. A refusal names each share by its place in `places`,
   * as restore does.
   */
  static async combine(
    records: readonly string[],
    platform: ShareRepairPlatform,
    places?: readonly number[],
  ): Promise<ShareSet> {
    if (!records.some(isMarked)) return ShareSet.restore(records, platform, places);
    assertShareCount(records.length);
    const plan = await new JointRepair(platform).plan(records, { places });
    const { assessment } = plan;
    if (assessment.reason !== undefined || assessment.combinations > MAX_LIBRARY_TRIES) {
      // A plan that is not searched is wiped here; searchOnce wipes the one that is.
      plan.wipe();
      throw ERRORS.create("combine-refused", [
        assessment.reason ??
          "Too many combinations are open: read more of the marked elements, or add a share.",
      ]);
    }
    // Searched without a signal: nothing stops it.
    const { sets: found } = await searchOnce(plan);
    if (found.length === 0) throw ERRORS.create("no-phrase-fits", []);
    if (found.length > 1) throw ERRORS.create("more-than-one-phrase-fits-shares-read-more", []);
    return new ShareSet(defined(found[0]));
  }

  /** A phrase that a search of marked shares found (JointPlan.search), as a share set. */
  static of(set: RepairedSet): ShareSet {
    return new ShareSet(set);
  }

  /** Words of the phrase whose secret has `secretBytes`, as the shares and an assessment tell. */
  static wordCountOf(secretBytes: number): number {
    const words = wordCountOfEntropy(secretBytes);
    if (words === undefined) throw ERRORS.create("share-s-secret-no-bip39-length", []);
    return words;
  }

  /**
   * Why the phrases restored, `sets` of them, are not the wallet given: their own phrases, or,
   * after a search of `dateCombinations` dates with ?, the phrases those dates unmask.
   */
  static walletMismatch(sets: number, dateCombinations?: number): string {
    if (dateCombinations === undefined)
      return sets === 1
        ? "The phrase that these shares restore does not match the wallet given."
        : `None of the ${sets} phrases that fit these shares matches the wallet given.`;
    const dates = counted(dateCombinations, "date combination");
    return sets === 1
      ? `None of the ${dates} gives the wallet given.`
      : `None of the ${dates} gives the wallet given, with any of the ${sets} phrases that fit these shares.`;
  }

  /** The phrase that the shares hold: for a Seedshift backup, the masked phrase. */
  get mnemonic(): string {
    return this.#mnemonic.value;
  }

  /** Every share, in the order given, as read or repaired. */
  get shares(): readonly ReadRepairableShare[] {
    return this.#shares.shares;
  }

  /** Elements that the phrase does not depend on and nothing settles: their values are a guess. */
  get unsettled(): readonly MarkedElement[] {
    return this.#unsettled;
  }

  /** Shares, counted from 1, of a group with fewer than its threshold: they took no part. */
  get unchecked(): readonly number[] {
    return this.#unchecked ?? [];
  }

  /**
   * The warning for the shares that took no part, each named by its place in `places`, by its
   * index in the set; undefined when every share took part.
   */
  uncheckedNote(places?: readonly number[]): string | undefined {
    if (this.unchecked.length === 0) return undefined;
    const named = this.unchecked.map((share) => placeOf(places, share));
    return `Share ${named.join(", ")}: too few shares of its group to take part; not checked.`;
  }

  /** Whether every share took part in the restore and every element of it is settled. */
  get checked(): boolean {
    return this.unchecked.length === 0 && this.unsettled.length === 0;
  }

  /** Groups of the set that restore the phrase. */
  get groupThreshold(): number {
    return defined(this.#infos[0]).groupThreshold;
  }

  /** Groups of the set, given or not. */
  get groupCount(): number {
    return defined(this.#infos[0]).groupCount;
  }

  /** The groups of the shares given, in the order they first come. */
  get groups(): readonly ShareGroup[] {
    const topology = new SetTopology(this.#infos);
    return topology.groups.map((members) => ({
      index: defined(this.#infos[defined(members[0])]).groupIndex,
      threshold: topology.thresholdOf(members),
      members: members.map((member) => member + 1),
    }));
  }

  /** Bytes of the secret that the shares hold. */
  get secretBytes(): number {
    return defined(this.#infos[0]).secretLength;
  }

  /** Words of the phrase that the shares hold. */
  get wordCount(): number {
    return ShareSet.wordCountOf(this.secretBytes);
  }

  /** The form in which the backup that was split is shown again: that of its first share. */
  get backupForm(): EncodedFormat {
    return RESTORED_FORM[defined(this.shares[0]).format];
  }

  /**
   * The backup that was split, in the form its shares were written in, which the dates turn into
   * the seed phrase `mnemonic`; undefined where it would be the same words again.
   */
  backup(mnemonic: string): SetBackup | undefined {
    const form = this.backupForm;
    const text = formatEncoded(representMnemonic(this.mnemonic), form);
    return text === mnemonic ? undefined : { form, text };
  }

  /**
   * The wallet fingerprint of the phrase that the shares hold, by `fingerprintOf` (the host's BIP32
   * master fingerprint, with its seed function and an empty BIP39 passphrase), or undefined when
   * that phrase is no valid BIP39 phrase. For a Seedshift backup it is the encoded fingerprint, to
   * be compared with the one noted at encoding before any date is typed.
   */
  fingerprint<T>(fingerprintOf: (mnemonic: string) => T): T | undefined {
    return fingerprintOfValidPhrase(this.mnemonic, fingerprintOf);
  }

  /**
   * The set as plain data, as combineSskrShareSet and the searches give it; it cannot be changed.
   */
  toRepairedSet(): RepairedSet {
    return Object.freeze({
      mnemonic: this.mnemonic,
      shares: this.shares,
      unsettled: this.#unsettled,
      ...(this.#unchecked === undefined ? {} : { unchecked: this.#unchecked }),
    });
  }

  /** Ends the retained phrase/share lifetime; earlier caller-owned views remain independent. */
  wipe(): void {
    this.#mnemonic.wipe();
    this.#shares.wipe();
  }

  /** Ends this set after all asynchronous uses and any explicit child snapshots are complete. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class ShareExport extends Redacted implements Disposable {
  readonly #uris: SecretValue<readonly string[]>;
  readonly #shown: readonly Omit<WrittenShare, "ur">[];
  readonly #leftOut: readonly number[];
  readonly #total: number;

  private constructor(shown: readonly WrittenShare[], leftOut: readonly number[], total: number) {
    super("ShareExport");
    // Copied and frozen: the getters hand them out, and what is shown, saved and named must stay
    // what the export settled.
    this.#shown = Object.freeze(
      shown.map(({ format, number }) => Object.freeze({ format, number })),
    );
    this.#leftOut = Object.freeze([...leftOut]);
    this.#total = total;
    this.#uris = SecretValue.texts(shown.map(({ ur }) => ur));
  }

  /**
   * The shares of `set`, repaired or not, named by `places`, by their index in the set; each in
   * `format`, or without it in the form it was written in.
   */
  static of(set: RepairedShares, places: readonly number[], format?: ShareFormat): ShareExport {
    // Refused here, where it is bound to the shares, not once a share is written (AUD-001-API001).
    if (format !== undefined) assertShareFormat(format);
    // Array.from turns holes into undefined, which is refused: each share is named by its place,
    // and a missing one would be shown as "Share undefined".
    const named = Array.from(places);
    if (
      named.length < set.shares.length ||
      !named.every((place) => Number.isSafeInteger(place) && place >= 1)
    )
      throw ERRORS.create("each-share-place-among-typed-whole-number-from", []);
    const leftOut = [...new Set(set.unsettled.map((element) => placeOf(named, element.share)))];
    const shown = set.shares.flatMap((share, index) =>
      leftOut.includes(defined(named[index]))
        ? []
        : [{ ur: share.ur, format: format ?? share.format, number: defined(named[index]) }],
    );
    return new ShareExport(shown, leftOut, Math.max(...named));
  }

  /** The places of the shares left out, with an element that nothing settles. */
  get leftOut(): readonly number[] {
    return this.#leftOut;
  }

  /** Why each share left out is left out, one line each. */
  leftOutMessages(): string[] {
    return this.#leftOut.map(
      (place) =>
        `Share ${place} cannot be settled and is left out: read more of it, or use another copy.`,
    );
  }

  /** The shares to show, in the order typed, copies included. */
  get shown(): readonly WrittenShare[] {
    const uris = this.#uris.value;
    return Object.freeze(
      this.#shown.map((share, index) => Object.freeze({ ...share, ur: defined(uris[index]) })),
    );
  }

  /** The shares to save: each once. */
  get saved(): readonly WrittenShare[] {
    return distinct(this.shown);
  }

  /** The forms of the shares saved, each once, in their order. */
  get forms(): readonly ShareFormat[] {
    return [...new Set(this.saved.map((share) => share.format))];
  }

  /** The shares shown, by place, as a check that they belong to one set takes them. */
  get members(): readonly { readonly place: number; readonly ur: string }[] {
    return this.shown.map((share) => ({ place: share.number, ur: share.ur }));
  }

  /** The highest place of the shares typed: the shares are shown as "N of" it. */
  get total(): number {
    return this.#total;
  }

  /** The note for copies saved once, or undefined when no share was typed twice. */
  get copiesNote(): string | undefined {
    return this.saved.length < this.#shown.length
      ? "Copies of one share are saved once."
      : undefined;
  }

  /** The same shares, every one in `format`, as cards show them. */
  inForm(format: ShareFormat): ShareExport {
    assertShareFormat(format);
    return new ShareExport(
      this.shown.map((share) => ({ ...share, format })),
      this.#leftOut,
      this.#total,
    );
  }

  /** Ends retained export URs, leaving independent inForm copies and borrowed sets untouched. */
  wipe(): void {
    this.#uris.wipe();
  }

  /** Ends this export after its display and asynchronous saves have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export type Unmasked =
  | {
      readonly kind: "phrases";
      readonly phrases: readonly UnmaskedPhrase[];
      /** Every phrase for a candidate list, also the matches of a search beyond those shown. */
      readonly listed: readonly string[];
    }
  | { readonly kind: "dates"; readonly message: string }
  /** The host stopped the date search (DateSearchRun.signal): no phrase is told (CORE-22). */
  | { readonly kind: "stopped" };

export class ShareUnmasking extends Redacted {
  readonly #mode: ShareMode;
  readonly #dates: DatesAnswer | undefined;
  readonly #walletCheck: WalletCheck | undefined;
  readonly #maxShown: number | undefined;
  readonly #keep: number | undefined;

  constructor(options: UnmaskingOptions) {
    super("ShareUnmasking");
    Masking.assertSplitMode(options.mode);
    const masked = Masking.isMaskedMode(options.mode);
    if (masked && !(options.dates instanceof DatesAnswer))
      throw ERRORS.create("seedshift-phrase-unmasked-dates-dates-answer", []);
    Masking.of(options.mode).assertDateCount(options.dates?.count ?? 0);
    this.#mode = options.mode;
    this.#dates = masked ? options.dates : undefined;
    this.#walletCheck = options.walletCheck;
    this.#maxShown = options.maxShown;
    this.#keep = options.keep;
  }

  /** Whether a date holds ?, so that each phrase of the shares is searched. */
  get searches(): boolean {
    return this.#dates?.hasForgottenDigits === true;
  }

  /**
   * The date combinations that each phrase is searched with, which a wallet that no phrase matches
   * is said against (ShareSet.walletMismatch); undefined without a search.
   */
  get searchedCombinations(): number | undefined {
    return this.searches ? defined(this.#dates).combinations : undefined;
  }

  /** Whether the search needs the wallet to tell the right dates (walletNeeded). */
  get needsWallet(): boolean {
    return this.searches && walletNeeded(this.#mode);
  }

  /**
   * The date search that each phrase of the shares needs, for its time: its combinations, and the
   * seconds that each takes, from the decoding of one combination (DateSearch
   * .secondsPerCombination) and, with a wallet check, the checks that one combination costs in
   * this mode (Masking.checksPerCombination) at the pace of the host's check (DateSearch
   * .secondsPerCheck). Undefined without a search.
   */
  async dateWork(now?: MonotonicClock): Promise<DateWork | undefined> {
    // Only a masked phrase has dates to search.
    const mode = this.#mode;
    if (!this.searches || !Masking.isMaskedMode(mode)) return undefined;
    const dates = defined(this.#dates);
    // The shares do not say yet how long their phrase is; every count of dates fits 24 words.
    const perCombination = DateSearch.secondsPerCombination(mode, dates, LONGEST_PHRASE, now);
    if (this.#walletCheck === undefined)
      return { combinations: dates.combinations, secondsEach: perCombination };
    const pace = {
      perCombination,
      perCheck: await DateSearch.secondsPerCheck(this.#walletCheck, now),
    };
    const checks = Masking.of(mode).checksPerCombination(ANY_WORD_COUNT);
    return { combinations: dates.combinations, secondsEach: secondsEach(pace, checks) };
  }

  /**
   * The phrases that `sets` give, in their order: each set's own phrase, or the phrases that the
   * dates unmask, searched with `run` where a date holds ?; only those of the wallet when a wallet
   * check was given. Refused, with the line that says why, when the dates are more than a set's
   * phrase takes.
   */
  async unmask(sets: readonly RepairedSet[], run: DateSearchRun = {}): Promise<Unmasked> {
    // Snapshot every input before the first host callback can change a later set or its phrase.
    // Read mnemonic once, even when a JavaScript host supplies an accessor for it.
    const owned = Array.from(sets, ({ mnemonic, shares, unsettled, unchecked }) => ({
      mnemonic,
      shares: shares.map(({ ur, format, repaired, filled }) => ({
        ur,
        format,
        repaired,
        filled: filled.map(({ position, value }) => ({ position, value })),
      })),
      unsettled: unsettled.map(({ share, position }) => ({ share, position })),
      ...(unchecked === undefined ? {} : { unchecked: [...unchecked] }),
    }));
    const phrases: UnmaskedPhrase[] = [];
    const listed: string[] = [];
    const mode = this.#mode;
    for (const set of owned) {
      if (this.#dates === undefined || !Masking.isMaskedMode(mode)) {
        if (await this.#matches(set.mnemonic)) phrases.push({ set, mnemonic: set.mnemonic });
        continue;
      }
      using backup = EncodedBackup.read(set.mnemonic, "english", mode);
      const tooMany = this.#dates.tooManyFor(backup.indexes.length);
      if (tooMany !== undefined) return { kind: "dates", message: tooMany };
      if (!this.#dates.hasForgottenDigits) {
        const mnemonic = backup.decode(this.#dates.known).recoveredMnemonic;
        if (await this.#matches(mnemonic)) phrases.push({ set, mnemonic });
        continue;
      }
      const keep = this.#keep ?? 0;
      using search = new DateSearch({
        indexes: backup.indexes,
        dates: this.#dates,
        mode,
        walletCheck: this.#walletCheck,
        maxShown: this.#maxShown,
        keep,
      });
      const result = await search.run(run);
      if (result.stopped) return { kind: "stopped" };
      for (const match of result.shown)
        phrases.push({
          set,
          mnemonic: match.mnemonic,
          dates: match.dates,
          matchedAt: match.evidence,
        });
      // A list takes every match; without one, those shown stand for the matches.
      listed.push(...(keep > 0 ? result.kept : result.shown.map((match) => match.mnemonic)));
    }
    // The phrases of direct sets and of whole dates are listed as they are kept.
    if (!this.searches) listed.push(...phrases.map((phrase) => phrase.mnemonic));
    return { kind: "phrases", phrases, listed };
  }

  /** Whether `mnemonic` is the wallet's; every phrase is without a wallet check. */
  async #matches(mnemonic: string): Promise<boolean> {
    return (
      this.#walletCheck === undefined || (await askWallet(this.#walletCheck, mnemonic)).matched
    );
  }
}

export class ShareValues extends Redacted implements Disposable {
  readonly #layout: readonly ShareLayout[];
  readonly #texts: SecretValue<readonly string[]>;

  constructor(shares: readonly ReadRepairableShare[]) {
    super("ShareValues");
    if (!Array.isArray(shares)) throw ERRORS.create("shape", []);
    const admitted: readonly unknown[] = shares;
    const texts: string[] = [];
    this.#layout = Object.freeze(
      Array.from(admitted, (share) => {
        if (typeof share !== "object" || share === null) throw ERRORS.create("shape", []);
        const ur: unknown = Reflect.get(share, "ur");
        const format: unknown = Reflect.get(share, "format");
        const repaired: unknown = Reflect.get(share, "repaired");
        const filled: unknown = Reflect.get(share, "filled");
        assertShareFormat(format);
        if (typeof ur !== "string" || typeof repaired !== "boolean" || !Array.isArray(filled))
          throw ERRORS.create("shape", []);
        texts.push(ur);
        const elements: readonly unknown[] = filled;
        const positions = Array.from(elements, (element) => {
          if (typeof element !== "object" || element === null) throw ERRORS.create("shape", []);
          const position: unknown = Reflect.get(element, "position");
          const value: unknown = Reflect.get(element, "value");
          if (!inWholeRange(position, wholeNumbersFrom(1)) || typeof value !== "string")
            throw ERRORS.create("shape", []);
          texts.push(value);
          return position;
        });
        return Object.freeze({ format, repaired, positions: Object.freeze(positions) });
      }),
    );
    // Preserve caller-supplied code units as well as ordinary transport text; no normalization.
    this.#texts = SecretValue.utf16Texts(texts);
  }

  /** Fresh frozen views; a later disposal cannot recall strings already given to a caller. */
  get shares(): readonly ReadRepairableShare[] {
    const texts = this.#texts.value;
    let next = 0;
    return Object.freeze(
      this.#layout.map(({ format, repaired, positions }) => {
        const ur = defined(texts[next++]);
        const filled = positions.map((position) =>
          Object.freeze({ position, value: defined(texts[next++]) }),
        );
        return Object.freeze({ ur, format, repaired, filled: Object.freeze(filled) });
      }),
    );
  }

  /** Refuses new secret reads after this owner ends, including across an awaited operation. */
  assertLive(): void {
    this.#texts.assertLive();
  }

  /** Overwrites retained text buffers as far as the JavaScript runtime permits; idempotent. */
  wipe(): void {
    this.#texts.wipe();
  }

  /** Ends the containing owner's scope after its uses have settled. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export class Share extends Redacted {
  readonly #ur: SecretValue<string>;
  readonly #format: ShareFormat;
  /** Read once, with the share: every question about its set, group and member is asked of it. */
  readonly #info: ShareInfo;

  private constructor(ur: string, format: ShareFormat) {
    super("Share");
    this.#format = format;
    this.#info = Object.freeze(wipedAfter(urToTransport(ur), shareInfo));
    this.#ur = SecretValue.text(ur);
  }

  /** The forms that a share is written in (SHARE_FORMATS). */
  static readonly FORMATS: readonly ShareFormat[] = SHARE_FORMATS;

  /** Reads a share in any of its forms; throws why it cannot be read, without repeating it. */
  static read(text: string): Share {
    const { ur, format } = readShare(text);
    return new Share(ur, format);
  }

  /**
   * The shares of one set, each read in any of its forms, checked together before the SSKR
   * library sees them: as many as a set may have, none of another set, no member twice, one
   * threshold for each group, and, with `requireQuorum`, enough of them for the set's threshold.
   */
  static readSet(records: readonly string[], requireQuorum = true): Share[] {
    assertShareCount(records.length);
    const shares: Share[] = [];
    try {
      for (const record of records) shares.push(Share.read(record));
      const infos = shares.map((share) => share.info);
      const conflict = SetTopology.firstConflict(infos);
      if (conflict !== undefined)
        throw ERRORS.create("read-set-refused", [SET_CONFLICT_TEXTS[conflict.kind].refusal]);
      if (requireQuorum && !new SetTopology(infos).enough)
        throw ERRORS.create("not-enough-sskr-shares-meet-recorded-threshold", []);
      return shares;
    } catch (error) {
      for (const share of shares) share.wipe();
      throw error;
    }
  }

  /** Whether `text` reads as a whole share: its own checksum makes other text pass one in 2^32. */
  static reads(text: string): boolean {
    try {
      readShare(text);
      return true;
    } catch {
      return false;
    }
  }

  /** The share as its UR, ur:sskr/…, the form that the SSKR library takes. */
  get ur(): string {
    return this.#ur.value;
  }

  /** The form the share was written in. */
  get format(): ShareFormat {
    return this.#format;
  }

  /** What the share's metadata says: its set, its group and its member. */
  get info(): ShareInfo {
    return this.#info;
  }

  /** The share written in `format`, by default the one it was read in. */
  write(format: ShareFormat = this.#format): string {
    return writeShare(this.#ur.value, format);
  }

  /** Whether `other` is the same share, however either of them was written. */
  sameAs(other: Share): boolean {
    return other.#ur.value === this.#ur.value;
  }
  /** Overwrites this share's retained UR bytes; returned text copies cannot be recalled. */
  wipe(): void {
    this.#ur.wipe();
  }

  /** Ends this share's lifetime in its owning scope. */
  [Symbol.dispose](): void {
    this.wipe();
  }
}

export enum ShareEncoding {
  /**
   * The compact UR of a share (ur:sskr/...), its minimal Bytewords.
   */
  CompactUr = 0,
  /**
   * The standard Bytewords of a share's tagged CBOR.
   */
  Bytewords = 1,
}

